(window.WCD=window.WCD||[]).push(["disney",[["Q27188178",2,"film","Aladdin, film de 2019","E","Aladdin est un film d'aventures fantastique américain coécrit et réalisé par Guy Ritchie et sorti en 2019. Il s'agit de l’adaptation en prise de vues réelles du film d'animation du même nom sorti en 1992, dans la lignée des films de Walt Disney Pictures comme Le Livre de la jungle en 2016, La Belle et la Bête en 2017, et Dumbo en 2019.","Aladdin est un film d'aventures fantastique américain coécrit et réalisé par Guy Ritchie et sorti en 2019.","fr:Aladdin_(film,_2019)","https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Aladdin_2019_Logo_Black.svg/330px-Aladdin_2019_Logo_Black.svg.png"],["Q27660145",3,"film","Blanche Neige","E","Blanche Neige est un film américain réalisé par Marc Webb et sorti en 2025.",null,"fr:Blanche_Neige_(film,_2025)","https://upload.wikimedia.org/wikipedia/en/thumb/1/1f/Snow_White_%282025_film%29_final_poster.jpg/330px-Snow_White_%282025_film%29_final_poster.jpg"],["Q24284363",5,"film","Cruella","L","Cruella est un film américain réalisé par Craig Gillespie, sorti en 2021.",null,"fr:Cruella_(film)","https://upload.wikimedia.org/wikipedia/fr/thumb/5/5e/Cruella_%28film%2C_logo%29.jpg/330px-Cruella_%28film%2C_logo%29.jpg"],["Q113879962",6,"film","Elio","R","Elio est un film d'animation en images de synthèse américain réalisé par Madeline Sharafian, Domee Shi et Adrian Molina et sorti en 2025.",119,"fr:Elio","c:c/ce/Elio_film_logo.png"],["Q53110",8,"film","High School Musical : Premiers pas sur scène","R","High School Musical: Premiers pas sur scène est un téléfilm américain de la collection des Disney Channel Original Movie, réalisé par Kenny Ortega et diffusé en 2006.",114,"fr:High_School_Musical_:_Premiers_pas_sur_scène","https://upload.wikimedia.org/wikipedia/fr/thumb/b/b1/High_School_Musical_%28logo%29.png/330px-High_School_Musical_%28logo%29.png",{"cats":["disney","enfance"]}],["Q431140",9,"film","Hocus Pocus : Les Trois Sorcières","M","Hocus Pocus: Les Trois Sorcières, ou Abracadabra au Québec, est un film américain réalisé par Kenny Ortega et sorti en 1993.",118,"fr:Hocus_Pocus_:_Les_Trois_Sorcières","c:f/f3/Bette_Midler_2015_%282%29.jpg"],["Q490464",10,"film","Il était une fois","R","Il était une fois est un film américain réalisé par Kevin Lima et sorti en 2007.",null,"fr:Il_était_une_fois_(film,_2007)","https://upload.wikimedia.org/wikipedia/en/thumb/2/2a/Enchantedposter.jpg/330px-Enchantedposter.jpg"],["Q19946102",12,"film","La Belle et la Bête, film de 2017","R","La Belle et la Bête est un film musical fantastique américain réalisé par Bill Condon et sorti en 2017.",null,"fr:La_Belle_et_la_Bête_(film,_2017)","https://upload.wikimedia.org/wikipedia/fr/thumb/5/59/La_Belle_et_la_B%C3%AAte_%28film%2C_2017%29_Logo.png/330px-La_Belle_et_la_B%C3%AAte_%28film%2C_2017%29_Logo.png"],["Q24357415",14,"film","La Petite Sirène, film de 2023","R","La Petite Sirène est un film musical fantastique américain réalisé par Rob Marshall et sorti en 2023. Il s'agit d'un remake en prise de vues réelles du « Classique d'animation » des studios Disney La Petite Sirène sorti en 1989. Le classique d'animation est, lui-même, inspiré du conte du même nom de Hans Christian Andersen, publié en 1836.","La Petite Sirène est un film musical fantastique américain réalisé par Rob Marshall et sorti en 2023.","fr:La_Petite_Sirène_(film,_2023)","https://upload.wikimedia.org/wikipedia/fr/thumb/7/7e/La_Petite_Sir%C3%A8ne_%28film%2C_2023%29.png/330px-La_Petite_Sir%C3%A8ne_%28film%2C_2023%29.png"],["Q59395971",18,"film","Lilo et Stitch","R","Lilo et Stitch est un film américain réalisé par Dean Fleischer Camp et sorti en 2025. Il s'agit d'un remake en prise de vues réelles du film d'animation Lilo et Stitch, sorti en 2002.","Lilo et Stitch est un film américain réalisé par Dean Fleischer Camp et sorti en 2025.","fr:Lilo_et_Stitch_(film,_2025)","https://upload.wikimedia.org/wikipedia/fr/thumb/d/d0/Lilo_et_Stitch_%28film%2C_2025%29.png/330px-Lilo_et_Stitch_%28film%2C_2025%29.png"],["Q172271",19,"film","Maléfique","E","Maléfique est un film de fantasy américain en 3D réalisé par Robert Stromberg, sorti en 2014. Il s'agit du 5e « remake live action » des Studios Disney. Il raconte l'histoire de Maléfique, la méchante sorcière de La Belle au bois dormant. Il s'agit à la fois d'un film dérivé et d'une réadaptation du film d'animation La Belle au bois dormant.","Maléfique est un film de fantasy américain en 3D réalisé par Robert Stromberg, sorti en 2014.","fr:Maléfique_(film,_2014)","https://upload.wikimedia.org/wikipedia/en/thumb/5/55/Maleficent_poster.jpg/330px-Maleficent_poster.jpg"],["Q209170",20,"film","Mary Poppins","E","Mary Poppins est un film musical américain de Robert Stevenson adapté du roman éponyme de Pamela L. Travers et sorti en 1964. Mêlant prises de vues réelles et animation, il est considéré comme le 23e long métrage d'animation des studios Disney.","Mary Poppins est un film musical américain de Robert Stevenson adapté du roman éponyme de Pamela L.","fr:Mary_Poppins_(film)","https://upload.wikimedia.org/wikipedia/fr/thumb/e/e1/Mary_Poppins_%28Logo_de_1988%29.png/330px-Mary_Poppins_%28Logo_de_1988%29.png"],["Q114242678",21,"film","Mufasa : Le Roi lion","E","Mufasa: Le Roi lion est un film américain réalisé par Barry Jenkins et sorti en 2024. Il s'agit d'une préquelle au film Le Roi lion, lui-même remake photoréaliste du film d'animation du même nom sorti en 1994.","Mufasa: Le Roi lion est un film américain réalisé par Barry Jenkins et sorti en 2024.","fr:Mufasa_:_Le_Roi_lion","https://upload.wikimedia.org/wikipedia/fr/thumb/4/44/Mufasa_-_Le_Roi_lion.png/330px-Mufasa_-_Le_Roi_lion.png"],["Q379873",22,"film","Qui veut la peau de Roger Rabbit","L","Qui veut la peau de Roger Rabbit est un film américain réalisé par Robert Zemeckis et sorti en 1988. Coproduit par Touchstone Pictures, Amblin Entertainment et Silver Screen Partners, ce film mêlant animation et prise de vues réelles est adapté du roman Qui a censuré Roger Rabbit ? de Gary K. Wolf publié en 1981.","Qui veut la peau de Roger Rabbit est un film américain réalisé par Robert Zemeckis et sorti en 1988.","fr:Qui_veut_la_peau_de_Roger_Rabbit","https://upload.wikimedia.org/wikipedia/fr/thumb/9/91/Qui_veut_la_peau_de_Roger_Rabbit_%3F_Logo.png/330px-Qui_veut_la_peau_de_Roger_Rabbit_%3F_Logo.png"],["Q170035",23,"film","Ratatouille","L","Ratatouille est le huitième film d'animation en images de synthèse des studios américains Pixar, écrit et réalisé par Brad Bird et sorti en salles en 2007.",117,"fr:Ratatouille_(film)","https://upload.wikimedia.org/wikipedia/fr/thumb/0/09/Ratatouille_%28film%29_Logo.png/330px-Ratatouille_%28film%29_Logo.png",{"cats":["disney","enfance"]}],["Q626483",25,"film","Tron","R","Tron est un film de science-fiction américain réalisé par Steven Lisberger et sorti en 1982.",null,"fr:Tron","https://upload.wikimedia.org/wikipedia/en/thumb/1/17/Tron_poster.jpg/330px-Tron_poster.jpg"],["Q124457266",26,"film","Vaiana 2","E","Vaiana 2, ou Moana 2 en version originale et version québécoise, est un long-métrage d'animation et le 63e « Classique d'animation » des studios Disney réalisé par David G. Derrick Jr., et sorti en 2024.",118,"fr:Vaiana_2","https://upload.wikimedia.org/wikipedia/en/thumb/7/73/Moana_2_poster.jpg/330px-Moana_2_poster.jpg"],["Q922193",27,"film","Winnie l'ourson (film, 2011)","PC","Winnie l'ourson est le 120e long-métrage d'animation et le 51e « Classique d'animation » des studios Disney. Mettant en scène Winnie l’ourson et les autres personnages créés par A. A. Milne, il est réalisé et co-écrit par Stephen J. Anderson et Don Hall, et sorti en 2011.","Winnie l'ourson est le 120e long-métrage d'animation et le 51e « Classique d'animation » des studios Disney.","fr:Winnie_l'ourson_(film,_2011)","https://upload.wikimedia.org/wikipedia/fr/thumb/0/07/Winnie_l%27ourson_%28film%2C_2011%29_Logo.png/330px-Winnie_l%27ourson_%28film%2C_2011%29_Logo.png"],["Q112801489",28,"film","Élémentaire","R","Élémentaire est un film d'animation américain réalisé par Peter Sohn et produit par Walt Disney Pictures et Pixar Animation Studios sorti en 2023.",113,"fr:Élémentaire_(film)","c:6/6b/Elemental_logo.jpg"],["Q130742029",29,"perso","Anxiété (Vice-versa)","C","Anxiété est l'émotion orange et survoltée de Vice-versa 2 (Pixar, 2024). Elle arrive dans la tête de Riley au début de son adolescence et prend les commandes.","","en:Anxiety_(Inside_Out)","https://upload.wikimedia.org/wikipedia/en/thumb/e/ef/Anxiety_%28Inside_Out%29.png/330px-Anxiety_%28Inside_Out%29.png"],["Q519034",30,"perso","Aurore","PC","La princesse Aurore est un personnage de fiction inspiré par le personnage du conte La Belle au bois dormant de Charles Perrault et des frères Grimm et qui est apparu pour la première fois dans le long métrage d'animation La Belle au bois dormant, en 1959. Elle fait partie de la franchise Disney Princess.",119,"fr:Aurore_(Disney)","c:d/d0/Aurora_-_Sleeping_Beauty_1970_Reissue_Trailer.png"],["Q1860030",31,"perso","Bagheera","C","Bagheera est le nom d'une panthère noire, personnage du roman Le Livre de la jungle de Rudyard Kipling.",null,"fr:Bagheera","c:4/41/T2JB023_-_Bagheera_would_lie_out_on_a_branch.JPG"],["Q2245378",32,"perso","Baloo","PC","Baloo est le nom d'un ours, personnage du roman Le Livre de la jungle de Rudyard Kipling. C'est un vieux sage qui enseigne la loi de la jungle à Mowgli.","Baloo est le nom d'un ours, personnage du roman Le Livre de la jungle de Rudyard Kipling.","fr:Baloo","c:4/41/T2JB023_-_Bagheera_would_lie_out_on_a_branch.JPG"],["Q27688665",33,"perso","Bambi","C","Bambi est un faon de fiction créé par le romancier Felix Salten dans Bambi, l'histoire d'une vie dans les bois, paru en 1923. Le roman a été adapté au cinéma en 1942 par les studios Disney sous la forme d'un long métrage d'animation: Bambi.",119,"fr:Bambi_(personnage)","c:c/c9/Bambi-Hans-Bertle.jpg"],["Q16839317",34,"perso","Baymax","C","Baymax est le robot infirmier gonflable et câlin du film Les Nouveaux Héros (Disney, 2014), inspiré d'une équipe de Marvel. Il veille sur la santé de Hiro.","","en:Baymax","https://upload.wikimedia.org/wikipedia/en/thumb/2/21/Baymax_%28Marvel_Comics%29.jpg/330px-Baymax_%28Marvel_Comics%29.jpg"],["Q639184",35,"perso","Blanche-Neige","PC","Blanche-Neige est un conte de fées allemand dont la version la plus célèbre est celle recueillie et mise en forme par les frères Grimm, parue en 1812. Ce conte n'a pas d'équivalent dans le recueil français antérieur des contes de Perrault.",117,"fr:Sept_nains","c:3/31/Marianne_Stokes_Schneewittchen.jpg"],["Q20823443",36,"perso","Bo Peep","PC","Bo Peep est un personnage de fiction dans la franchise Toy Story créée par Pixar. Le personnage est interprété par Annie Potts. Bo apparaît dans les deux premiers films comme personnage secondaire, représenté comme un intérêt amoureux pour le protagoniste, le shérif Woody. Après avoir été donnée avant les événements de Toy Story 3, Bo revient en tant que personnage principal dans Toy Story 4, et fera une petite apparition dans Toy Story 5. Elle est inspirée par la comptine Little Bo-Peep.","Bo Peep est un personnage de fiction dans la franchise Toy Story créée par Pixar.","fr:Bo_Peep_(Toy_Story)","c:c/c0/Little_Bo_Peep_cosplayer_%2833483660770%29.jpg"],["Q2907795",37,"perso","Bob Razowski","R","Robert « Bob » Razowski est un personnage de fiction, apparaissant dans les films Monstres et Cie et Monstres Academy. Il est également présent dans les jeux vidéo dérivés du film, comme Monstres et Cie, Monstres et Cie: Atelier de jeux et Monstres et Cie: L'Île de l'épouvante. Il fait également une apparition dans le générique de fin du film Le Monde de Nemo, en tenue de plongée.","Robert « Bob » Razowski est un personnage de fiction, apparaissant dans les films Monstres et Cie et Monstres Academy.","fr:Bob_Razowski","c:0/03/Err%C3%B3_01_%286815421917%29.jpg"],["Q1799013",38,"perso","Bourriquet","PC","Bourriquet est un petit équidé de fiction imaginé par Walt Disney et Alan Alexander Milne en 1926 pour sa série de livres sur Winnie l'ourson. Bourriquet est devenu un des personnages principaux des adaptations cinématographiques des studios Disney à partir de 1966.",114,"fr:Bourriquet","c:6/67/Winnie-the-Pooh_166-1.png"],["Q110876326",39,"perso","Bruno Madrigal","C","Bruno Madrigal est l'oncle mystérieux d'Encanto (Disney, 2021), capable de voir l'avenir. Toute la famille évite d'en parler, d'où la chanson culte « Ne parlons pas de Bruno ».","","en:Bruno_Madrigal",""],["Q3658760",40,"perso","Carl Fredricksen","C","Carl Fredricksen est le vieux grincheux du film Là-haut (Pixar, 2009), qui fait s'envoler sa maison grâce à des milliers de ballons pour réaliser le rêve de sa défunte épouse.","","en:Carl_Fredricksen","https://upload.wikimedia.org/wikipedia/en/thumb/9/9f/Carl_from_Up_2009.png/330px-Carl_from_Up_2009.png"],["Q761417",41,"perso","Clarabelle Cow","C","Clarabelle est un personnage de fiction de l'univers de Mickey Mouse créé par Ub Iwerks à partir de 1928 pour les studios Disney. Elle fut baptisée Bellecorne puis Yvette avant d'adopter son nom définitif en 1935.",113,"fr:Clarabelle_Cow","c:4/4f/Clarabelle_Cow%2C_1930.jpg"],["Q1014855",42,"perso","Dash Parr","C","Dash Parr est le fils ultra-rapide de la famille des Indestructibles (Pixar). Ce gamin turbulent court plus vite que tout le monde, même sur l'eau.","","en:Dash_Parr","https://upload.wikimedia.org/wikipedia/en/thumb/2/25/Image_of_Dashiell_%22Dash%22_Par_as_he_appears_in_The_Incredibles_and_it%27s_sequel.png/330px-Image_of_Dashiell_%22Dash%22_Par_as_he_appears_in_The_Incredibles_and_it%27s_sequel.png"],["Q1753262",43,"perso","Donald Dingue","C","Le professeur Donald Dingue est un personnage de fiction de l'univers des canards créé par les studios Disney. Il apparaît pour la première fois à la télévision le 24 septembre 1961 en tant que présentateur du dessin animé éducatif An Adventure in Color diffusé dans Le Monde Merveilleux en couleurs de Walt Disney sur NBC.","Le professeur Donald Dingue est un personnage de fiction de l'univers des canards créé par les studios Disney.","fr:Donald_Dingue","c:b/b0/Ludwing_Von_Drake_-_Pluto.jpg"],["Q2490541",44,"perso","Edna Mode","PC","Edna Mode est la petite styliste excentrique des super-héros dans Les Indestructibles (Pixar). Sa règle d'or : « Pas de capes ! »","","en:Edna_Mode","https://upload.wikimedia.org/wikipedia/en/thumb/f/fc/Edna_Mode_promotional_image.png/330px-Edna_Mode_promotional_image.png"],["Q18636727",45,"perso","Flynn Rider","PC","Flynn Rider est un personnage de fiction qui apparaît dans le 50e film d'animation de studios Disney, Raiponce, abandonné par son père Carter il sera accueilli dans un foyer. Ainsi que dans le court-métrage Le Mariage de Raiponce et dans la série animée à venir.",111,"fr:Flynn_Rider","c:f/fd/Raiponce_-_20150803_16h45_%2810816%29.jpg"],["Q925172",46,"perso","Frère Lapin","PC","Frère Lapin est un lapin malin du folklore afro-américain, qui se sort de tous les pièges par la ruse. Disney l'a popularisé dans le film Mélodie du Sud (1946).","","en:Br'er_Rabbit","c:f/fb/Br%27er_Rabbit_and_Tar-Baby.jpg"],["Q1428120",47,"perso","Geppetto","C","Geppetto est un personnage du long métrage d'animation Pinocchio, adapté du roman Les Aventures de Pinocchio de Carlo Collodi paru en 1881.",117,"fr:Geppetto_(Disney)","c:1/14/Le_avventure_di_Pinocchio-pag020.jpg"],["Q854212",48,"perso","Gontran Bonheur","C","Gontran Bonheur, aussi appelé Jonathan le Veinard, est un personnage de fiction de l'univers des canards créé en 1948 par Carl Barks pour les studios Disney. Petit-fils de Grand-Mère Donald, il est le cousin de Donald Duck et rival auprès de Daisy.",117,"fr:Gontran_Bonheur","https://upload.wikimedia.org/wikipedia/en/thumb/2/22/GladstoneGander.jpg/330px-GladstoneGander.jpg"],["Q837005",49,"perso","Géo Trouvetou","C","Géo Trouvetou, parfois écrit Géo Trouvetout, est un personnage de fiction de l'univers des canards créé en mai 1952 par Carl Barks pour les studios Disney.",119,"fr:Géo_Trouvetou","c:4/4c/2024_Hasper_Kirmeszug_2.jpg"],["Q16251007",50,"perso","Hans","C","Hans est le prince des Îles du Sud dans La Reine des neiges (Disney, 2013). Charmant au premier abord, il se révèle être le grand méchant de l'histoire.","","en:Hans_(Frozen)",""],["Q16995485",51,"perso","Hiro Hamada","C","Hiro Hamada est le jeune génie de la robotique du film Les Nouveaux Héros (Disney, 2014), qui forme une équipe de super-héros avec le robot Baymax.","","en:Hiro_Takachiho","https://upload.wikimedia.org/wikipedia/en/thumb/3/38/Hiro_Takachiho_%28Marvel_Comics%29.jpg/330px-Hiro_Takachiho_%28Marvel_Comics%29.jpg"],["Q1051189",52,"perso","Horace Horsecollar","C","Horace est un personnage de fiction créé par Ub Iwerks en 1929 pour Walt Disney.",null,"fr:Horace_Horsecollar","c:d/d9/Horace_Horsecollar_Plow_boy_1929.jpg"],["Q2635399",53,"perso","Iago","C","Iago est un personnage de l'univers Disney d'Aladdin, apparu dans le long-métrage de 1992 et dans ses suites et œuvres dérivées. Perroquet essentiellement rouge et doué de parole, il est dans le long-métrage d'origine le compagnon et pendant comique de l'ennemi principal Jafar, et lui-même un ennemi des héros; il évolue ensuite, dans les suites et œuvres dérivées, en un personnage plus indépendant qui finira par fraterniser avec Aladdin et ses amis.",118,"fr:Iago_(Disney)","https://upload.wikimedia.org/wikipedia/en/thumb/d/da/IagoDisneyCharacter.png/330px-IagoDisneyCharacter.png"],["Q951483",54,"perso","Jasmine","PC","Jasmine est un personnage de fiction qui est apparu pour la première fois dans le long métrage d'animation Aladdin. Son prénom vient de l'arabe: الْأَمِيرَة يَاسَمِين. Elle est inspirée du personnage de la Princesse Badroulboudour du conte Aladin et la Lampe merveilleuse des Mille et Une Nuits. Le personnage apparaît dans les suites du film sorties directement en vidéo: Le Retour de Jafar et Aladdin et le Roi des voleurs, ainsi qu'une série télévisée, Aladdin et des bandes dessinées.","Jasmine est un personnage de fiction qui est apparu pour la première fois dans le long métrage d'animation Aladdin.","fr:Jasmine_(Disney)","c:4/47/D23_Expo_2015_-_Jasmine_%2820607061292%29.jpg"],["Q2200623",55,"perso","Jessie","R","Jessie est un personnage fictif des films Pixar Toy Story, interprété par Joan Cusack. Jessie apparaît pour la première fois dans Toy Story 2. Elle est un jouet rare inspiré du personnage de l'émission de télévision fictive Western Woody des années 1950, qui comprenait le shérif Woody, Jessie, Papi Pépite le prospecteur et Pile-Poil, le cheval de Woody.","Jessie est un personnage fictif des films Pixar Toy Story, interprété par Joan Cusack.","fr:Jessie_(Toy_Story)","c:3/3f/Wizard_World_Anaheim_2011_-_Jessie_from_Toy_Story_%285675031396%29.jpg"],["Q1028714",56,"perso","Jiminy Cricket","PC","Jiminy Cricket est un personnage de fiction qui apparaît pour la première fois en 1881 sous la plume de Carlo Collodi, auteur des Aventures de Pinocchio, comme « grillon parlant » écrasé par Pinocchio dans le roman.",118,"fr:Jiminy_Cricket","c:0/0b/Jiminy_Cricket_%28cropped%29.png"],["Q3809567",57,"perso","John Ratcliffe","C","John Ratcliffe, né en 1549 dans le Lancashire et mort en septembre 1609, est le capitaine du Discovery, l'un des trois navires qui ont navigué d'Angleterre pour l'actuelle Virginie afin de fonder une colonie. Il est ensuite devenu le deuxième gouverneur de la colonie en 1608 qui devint plus tard Jamestown.",118,"fr:John_Ratcliffe","c:4/46/Ratcliffe_Under_the_crown%2C_American_history_%281909%29_%2814589986637%29.jpg"],["Q1069773",58,"perso","José Carioca","C","José Carioca est un personnage de fiction de l'univers des canards créé par les studios Disney. Ce perroquet brésilien apparaît pour la première fois en 1942 dans le long-métrage d'animation Saludos Amigos aux côtés de Donald Duck.","José Carioca est un personnage de fiction de l'univers des canards créé par les studios Disney.","fr:José_Carioca","c:7/7e/387_Bombardment_Sq_emblem.png"],["Q123398284",59,"perso","Joie (Vice-versa)","C","Joie est l'émotion principale de Vice-versa (Pixar, 2015), toujours positive et pleine d'énergie, qui veille à ce que Riley reste heureuse.","","en:Joy_(Inside_Out)","https://upload.wikimedia.org/wikipedia/en/thumb/3/30/Joy_-_Inside_Out.webp/330px-Joy_-_Inside_Out.webp"],["Q275475",60,"perso","Kaa","C","Kaa est un personnage de fiction du roman Le Livre de la jungle de Rudyard Kipling. Il apparait dans le long métrage d'animation Le Livre de la jungle de Walt Disney Pictures.","Kaa est un personnage de fiction du roman Le Livre de la jungle de Rudyard Kipling.","fr:Kaa","c:f/f2/T2JB159_-_Jungle_Book_capital_K.JPG"],["Q17088661",61,"perso","Kristoff","C","Kristoff est le vendeur de glace bourru mais gentil de La Reine des neiges (Disney), toujours accompagné de son fidèle renne Sven.","","en:Kristoff_(Frozen)","https://upload.wikimedia.org/wikipedia/en/thumb/2/2e/Kristoff_Bjorgman.png/330px-Kristoff_Bjorgman.png"],["Q178776",62,"perso","Lapin blanc","PC","Le Lapin blanc est un personnage de fiction du livre Les Aventures d'Alice au pays des merveilles de Lewis Carroll. Il est l'un des personnages les plus célèbres de l'univers de cette histoire.","Le Lapin blanc est un personnage de fiction du livre Les Aventures d'Alice au pays des merveilles de Lewis Carroll.","fr:Lapin_blanc","c:e/ec/Down_the_Rabbit_Hole.png"],["Q1798441",63,"perso","Les Rapetou","C","Les Rapetou sont des personnages de fiction de l'univers des canards créés en 1951 par Carl Barks pour les studios Disney. La cible principale de cette bande de gangsters est l'argent que Balthazar Picsou a enfermé dans son coffre-fort. Dans la bande dessinée, le haut de leur visage n'est jamais visible sans leur masque, les auteurs en profitant souvent pour introduire des scènes humoristiques.",114,"fr:Les_Rapetou","c:0/0b/Panzerknacker_in_Stein.JPG"],["Q2367867",64,"perso","Loup","PC","Le loup, parfois surnommé grand méchant loup, est un personnage traditionnel de conte qui apparaît dans plusieurs récits folkloriques, tels certaines des fables d'Ésope et les contes de Grimm.",113,"fr:Loup_(personnage_de_conte)","c:a/a2/Little_Red_Riding_Hood_%28136547330%29.jpg"],["Q1141265",65,"perso","Madame de Trémaine","C","Madame de Trémaine plus couramment appelée Belle-mère ou marâtre est le personnage antagoniste du long métrage d'animation Cendrillon adapté du conte de Charles Perrault, Cendrillon ou la Petite Pantoufle de verre paru en 1697, et de la version des frères Grimm, Aschenputtel, publiée en 1812.",110,"fr:Madame_de_Trémaine","https://upload.wikimedia.org/wikipedia/en/thumb/8/8c/LadyTremaine.png/330px-LadyTremaine.png"],["Q6786487",66,"perso","Martin","PC","Martin est un personnage de fiction, apparaissant dans le film Cars et ses suites. Il est également le héros des jeux vidéo dérivés du film, comme Cars: Quatre Roues ou Cars: La Coupe internationale de Martin. Martin est une dépanneuse, inspiré par un véhicule de 1951 d'International Harvester. Il interprété dans la version originale par Larry the Cable Guy et dans la version française par Michel Fortin puis Gilles Lellouche dans Cars 2 et Cars 3 et Jean-Pierre Gernez dans la série Cars Toon et Cars: Sur la Route.","Martin est un personnage de fiction, apparaissant dans le film Cars et ses suites.","fr:Martin_(Cars)","c:e/e7/Pixar_Cars_at_Igromir_2011_%286219388887%29.jpg"],["Q24455661",67,"perso","Maui","PC","Maui est le demi-dieu métamorphe et vantard de Vaiana (Disney, 2016), doublé par Dwayne Johnson en VO. Ses tatouages bougent et commentent ses actions.","","en:Maui_(Moana)","https://upload.wikimedia.org/wikipedia/en/thumb/5/57/Maui_Disney.webp/330px-Maui_Disney.webp"],["Q1141437",68,"perso","Max","PC","Max est un personnage de fiction créé par la Walt Disney Company en 1992. Il est le fils de Dingo apparu dans la série télévisée d'animation La Bande à Dingo","Max est un personnage de fiction créé par la Walt Disney Company en 1992.","fr:Max_(Dingo)","https://upload.wikimedia.org/wikipedia/en/thumb/c/c1/Max_Goof.jpg/330px-Max_Goof.jpg"],["Q12094271",69,"perso","Megara","C","Megara est un personnage de fiction qui est apparu pour la première fois dans le long métrage d'animation Hercule. Elle est inspirée du personnage Mégara de la mythologie grecque.","Megara est un personnage de fiction qui est apparu pour la première fois dans le long métrage d'animation Hercule.","fr:Megara_(Disney)","c:3/31/2014_Dragon_Con_Cosplay_-_Megara_%2815101056226%29.jpg"],["Q27179995",70,"perso","Merlin","C","Merlin est l'enchanteur excentrique du film Merlin l'Enchanteur (Disney, 1963), qui fait l'éducation du jeune Arthur, futur roi.","","en:Merlin_(Disney)","https://upload.wikimedia.org/wikipedia/en/thumb/a/a4/Merlin_-_DisneyCharacter.jpg/330px-Merlin_-_DisneyCharacter.jpg"],["Q107453681",72,"perso","Mirabel Madrigal","C","Mirabel Madrigal est l'héroïne d'Encanto (Disney, 2021), la seule de sa famille à ne pas avoir reçu de don magique, qui va pourtant sauver la maison.","","en:Mirabel_Madrigal","https://upload.wikimedia.org/wikipedia/en/thumb/e/e7/Mirabel_Madrigal.png/330px-Mirabel_Madrigal.png"],["Q1647361",73,"perso","Miss Tick","C","Miss Tick est un personnage de fiction de l'univers des canards, créé en 1961 par Carl Barks pour les studios Disney.",null,"fr:Miss_Tick","c:0/06/Wuppertal%2C_Streetart-Zyklus_%27Seifenkistenrennen%27_am_Fu%C3%9Fweg_Hildburgstra%C3%9Fe_-_H%C3%BCgelstra%C3%9Fe_%2822_-_Berliner_Str._205%2C_Anbau-Nordwand%29.jpg"],["Q13561019",74,"perso","Monsieur Mouche","C","Monsieur Mouche est un personnage de Peter Pan.",null,"fr:Monsieur_Mouche","c:7/70/Edward_Kipling_as_Smee_in_the_film_Peter_Pan_%281924%29.jpg"],["Q839484",75,"perso","Mushu","C","Mushu est le petit dragon bavard de Mulan (Disney, 1998), chargé de protéger l'héroïne. En VF, il a la voix de José Garcia.","","en:Mushu","https://upload.wikimedia.org/wikipedia/en/thumb/1/10/Mushu.png/330px-Mushu.png"],["Q6819227",76,"perso","Mérida","PC","Mérida est le personnage principal du long métrage d'animation Rebelle, sorti en 2012. Elle fait partie de la franchise Disney Princess. Elle est présente dans un épisode de Princesse Sofia. On la retrouve dans Ralph 2.","Mérida est le personnage principal du long métrage d'animation Rebelle, sorti en 2012.","fr:Mérida_(Disney)","c:f/f2/Disneyland_Merida_shoots_her_bow.jpg"],["Q2365445",77,"perso","Nala","C","Nala est un personnage de lionne tiré du dessin animé Le Roi lion de Disney créé en 1994. Elle est l'amie d'enfance de Simba et la fille de Sarafina. Dans le deuxième épisode de la série, elle est l'épouse de Simba et la mère d'une petite lionne nommée Kiara et d'un petit lion nommé Kion.","Nala est un personnage de lionne tiré du dessin animé Le Roi lion de Disney créé en 1994.","fr:Nala_(Disney)","https://upload.wikimedia.org/wikipedia/en/thumb/b/b6/Nala_from_The_Lion_King.png/330px-Nala_from_The_Lion_King.png"],["Q1419509",78,"perso","Oswald le lapin chanceux","R","Oswald le lapin chanceux est une série de dessins animés américains tournant autour du personnage du même nom créé par Ub Iwerks et Walt Disney en 1927 et distribués par Universal Pictures, qui en détenait les droits. Le personnage d'Oswald le lapin a commencé sa carrière en 1927, juste après la fin des Alice Comedies.",118,"fr:Oswald_le_lapin_chanceux","https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Oswald_jump.svg/330px-Oswald_jump.svg.png"],["Q1140361",79,"perso","Panchito Pistoles","C","Panchito Pistoles, de son vrai nom Panchito Romero Miguel Junipero Francisco Quintero Gonzalez, est un personnage de fiction de l'univers des canards créé par les studios Disney.",116,"fr:Panchito_Pistoles","https://upload.wikimedia.org/wikipedia/en/thumb/d/dd/Panchito_Pistoles_Duckipedia.png/330px-Panchito_Pistoles_Duckipedia.png"],["Q2915850",80,"perso","Panpan","C","Panpan, orthographié Pan-Pan dans les bandes dessinées, est un lapin américain de fiction tiré du dessin-animé Bambi de Disney. Il apparaît également dans Bambi 2. Il est rendu célèbre parce qu'il tape sans cesse son pied sur le sol afin de réveiller ses congénères. C'est d'ailleurs de ce geste que vient son nom. Son nom anglais est Thumper, du verbe thump, taper. Il est le meilleur ami de Bambi et le deuxième personnage du dessin-animé.",119,"fr:Panpan","c:6/6d/Thumper_-_Bambi_1942_trailer-max_noise_reduction.png"],["Q18217084",81,"perso","Pascal et Maximus","C","Pascal le caméléon et Maximus le cheval sont les deux compagnons animaux muets de Raiponce (Disney, 2010), aussi expressifs que drôles.","","en:Pascal_and_Maximus","https://upload.wikimedia.org/wikipedia/en/thumb/2/2f/Maximus_with_Pascal.jpg/330px-Maximus_with_Pascal.jpg"],["Q20712804",82,"perso","Peter Pan","C","Peter Pan est le garçon qui ne voulait pas grandir, héros de J. M. Barrie. Le film d'animation Disney de 1952 l'a rendu célèbre avec la fée Clochette et le capitaine Crochet.","","en:Peter_Pan_(franchise)",""],["Q2625989",83,"perso","Pocahontas","PC","Pocahontas est un personnage de fiction inspiré par le personnage réel de Pocahontas, Amérindienne de la confédération de tribus Powhatans et fille de Wahunsunacock.",118,"fr:Pocahontas_(Disney)","c:d/df/Pocahontas_%2827086381320%29.jpg"],["Q836719",84,"perso","Porcinet","PC","Porcinet est un personnage de fiction, créé par l'auteur Alan Alexander Milne, appartenant à l'univers de Winnie l'ourson. Le personnage a été repris dans différentes adaptations cinématographiques de l'œuvre, entre autres par Walt Disney Pictures et les studios Soyuzmultfilm.",112,"fr:Porcinet","c:c/c5/Winnie-the-Pooh_166-3.png"],["Q1140303",85,"perso","Princesses Disney","R","Disney Princess ou Princesses Disney est une franchise de The Walt Disney Company. Le principe de cette gamme transversale de Disney Consumer Products lancée en 1999 est de capitaliser sur les princesses des films de Walt Disney Pictures.","Disney Princess ou Princesses Disney est une franchise de The Walt Disney Company.","fr:Princesses_Disney","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Disney_Princess_2024_logo.svg/330px-Disney_Princess_2024_logo.svg.png"],["Q324433",86,"perso","Reine de cœur","PC","La Reine de cœur est un personnage fictif du livre pour enfants Les Aventures d'Alice au pays des merveilles de l'écrivain et mathématicien anglais Lewis Carroll, dans lequel elle apparaît comme l'antagoniste primaire.",111,"fr:Reine_de_cœur_(Alice_au_pays_des_merveilles)","c:e/e2/Alice%27s_Adventures_in_Wonderland_-_Carroll%2C_Robinson_-_S008_-_%27Off_with_her_head%21%27.jpg"],["Q11965",87,"perso","Riri, Fifi et Loulou","PC","Riri, Fifi et Loulou Duck sont des personnages de fiction de l'univers des canards créés en 1937 par Ted Osborne et Al Taliaferro pour les studios Disney.",118,"fr:Riri,_Fifi_et_Loulou","c:b/b2/U-Bahnhof_Oriente_-_Tick_Trick_und_Track_mit_Robben.jpg"],["Q3437147",88,"perso","Robin des Bois","C","Robin des Bois est un personnage de fiction apparu pour la première fois dans le film Robin des Bois. Le personnage est inspiré de Robin des Bois dans la légende du même nom. Il est apparu régulièrement dans Disney's tous en boîte.","Robin des Bois est un personnage de fiction apparu pour la première fois dans le film Robin des Bois.","fr:Robin_des_Bois_(Disney)","https://upload.wikimedia.org/wikipedia/en/thumb/0/0a/Robin_Hood_Disney_character.png/330px-Robin_Hood_Disney_character.png"],["Q2720481",89,"perso","Roi Louie","C","Le Roi Louie est un personnage de fiction qui est apparu pour la première fois dans le long métrage d'animation Le Livre de la jungle.",114,"fr:Roi_Louie","https://upload.wikimedia.org/wikipedia/en/thumb/8/8a/KingLouie.jpg/330px-KingLouie.jpg"],["Q7405109",90,"perso","Sally Carrera","C","Sally Carrera est une Porsche 911 bleue, avocate de la ville de Radiator Springs dans Cars (Pixar, 2006), dont Flash McQueen tombe amoureux.","","en:Sally_Carrera","https://upload.wikimedia.org/wikipedia/en/thumb/e/e1/Sally_Carrera.png/330px-Sally_Carrera.png"],["Q28018915",91,"perso","Sven","C","Sven est le renne fidèle et joueur de Kristoff dans La Reine des neiges (Disney). Il adore les carottes, qu'il partage avec Olaf.","","en:Sven_(Frozen)","https://upload.wikimedia.org/wikipedia/en/thumb/c/ce/Sven_from_Frozen.png/330px-Sven_from_Frozen.png"],["Q3820836",92,"perso","La Fée bleue","C","La Fée bleue (ou Fée aux cheveux turquoise) est la bonne fée de Pinocchio, le roman de Carlo Collodi (1883). C'est elle qui donne vie au pantin de bois dans le film Disney.","","en:Fairy_with_Turquoise_Hair","https://upload.wikimedia.org/wikipedia/en/thumb/6/64/Chiostri-pinocchio.jpg/330px-Chiostri-pinocchio.jpg"],["Q1237652",93,"perso","Le Terrible Requin","C","Le Terrible Requin est le monstre marin géant de Pinocchio (Collodi, 1883) qui avale Geppetto puis Pinocchio. Disney l'a remplacé par la baleine Monstro dans son film.","","en:The_Terrible_Dogfish","https://upload.wikimedia.org/wikipedia/en/thumb/d/dd/Terribile_pescecane.jpg/330px-Terribile_pescecane.jpg"],["Q958289",94,"perso","Tiana","PC","Tiana est un personnage de fiction qui est apparu pour la première fois en 2009 dans le long métrage d'animation La Princesse et la Grenouille. Cette jeune femme vit dans le vieux carré français de La Nouvelle-Orléans pendant les années 1920–1930. Serveuse, elle aspire à avoir son propre restaurant. Dans sa version originale, sa voix est doublée par Anika Noni Rose et pour la version française par China Moses.",115,"fr:Tiana_(Disney)","c:8/82/Anime_Expo_2010_-_LA_-_Disney%27s_Princess_and_the_Frog_%284837250782%29.jpg"],["Q403138",95,"perso","Tic et Tac","PC","Tic et Tac sont deux tamias, écureuils de fiction créés par les studios Disney en 1943.",null,"fr:Tic_et_Tac","c:2/22/Love_a_Parade._Disneyland._%2848874084926%29.jpg"],["Q1073705",96,"perso","Timon et Pumbaa","C","Timon le suricate et Pumbaa le phacochère sont le duo comique du Roi lion (Disney, 1994), qui enseigne à Simba la philosophie « Hakuna Matata ».","","en:Timon_and_Pumbaa","https://upload.wikimedia.org/wikipedia/en/thumb/9/91/Pumbaa.png/330px-Pumbaa.png"],["Q113956747",97,"perso","Vice-versa","C","Vice-versa est une franchise de Pixar créée par Pete Docter, qui se déroule dans la tête de Riley où ses émotions (Joie, Tristesse, Colère, Peur, Dégoût) prennent les commandes.","","en:Inside_Out_(franchise)","https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Inside_Out_%282015_film%29_Logo.svg/330px-Inside_Out_%282015_film%29_Logo.svg.png"],["Q3243369",98,"perso","Violette Parr","C","Violette Parr est la fille aînée des Indestructibles (Pixar), timide adolescente capable de devenir invisible et de créer des champs de force.","","en:Violet_Parr","https://upload.wikimedia.org/wikipedia/en/thumb/5/51/Violet_Parr.png/330px-Violet_Parr.png"],["Q58815184",99,"perso","Ralph la Casse","C","Ralph la Casse est le héros des Mondes de Ralph (Disney, 2012) : un méchant de jeu d'arcade au grand cœur, fatigué de casser des immeubles, qui part prouver qu'il peut être un gentil.","","en:Wreck-It_Ralph_(franchise)","https://upload.wikimedia.org/wikipedia/en/thumb/6/6c/Wreck-It_Ralph_logo.svg/330px-Wreck-It_Ralph_logo.svg.png"],["Q54954056",100,"parc","Avengers Campus","C","Avengers Campus est une zone thématique sur l'univers cinématographique Marvel des parcs à thèmes de Disney, ouvert à Disney California Adventure en Californie, à Hong Kong Disneyland et à Disney Adventure World en France. Le land de Hong Kong Disneyland ne se nomme pas Avengers Campus, mais Stark Expo.",117,"fr:Avengers_Campus","c:5/52/Disney_California_Adventure_%2851242299125%29.jpg",{"cats":["disney","parcs"]}],["Q859406",101,"parc","Big Thunder Mountain","PC","Big Thunder Mountain ou Big Thunder Mountain Railroad est une attraction de type montagnes russes des Royaumes enchantés de Disney. C'est un « train fou » lancé dans une mine du Far West, ce qui en fait la version Disney du train de la mine.",110,"fr:Big_Thunder_Mountain","c:9/9b/Big_Thunder_Mountain_%C3%A0_Disneyland_Paris_%283%29.jpg",{"cats":["disney","parcs"]}],["Q2742709",102,"parc","Château de Cendrillon","C","Le Château de Cendrillon est le château de contes de fées occupant la place centrale de deux parcs à thèmes Disney: Magic Kingdom et Tokyo Disneyland. D'inspiration néogothique, son architecture est issue des esquisses de l'imagineer Herbert Ryman.",115,"fr:Château_de_Cendrillon","c:8/84/Cinderella_Castle.jpg"],["Q2746222",103,"parc","Château de la Belle au bois dormant","C","Le Château de la Belle au bois dormant est le château de contes de fées occupant la place centrale de deux parcs à thèmes Disney: Disneyland et le Parc Disneyland. Il est situé dans la zone Fantasyland.",114,"fr:Château_de_la_Belle_au_bois_dormant","c:b/bd/Sleeping_Beauty_Castle_-_February_2024.png"],["Q1142089",104,"parc","Crush's Coaster","C","Crush's Coaster est une attraction ouverte depuis le 9 juin 2007 au sein de la zone Worlds of Pixar, dans le parc Disney Adventure World. L'attraction est à la fois un parcours de montagnes russes tournoyantes enfermées, dont les véhicules prennent la forme de tortues, et un parcours scénique sur l'univers du Monde de Nemo.",113,"fr:Crush's_Coaster","c:e/e8/Crush%E2%80%99s_Coaster%2C_Worlds_of_Pixar%2C_Disney_Adventure_World%2C_Disneyland_Paris.jpg",{"cats":["disney","parcs"]}],["Q764906",105,"parc","Disney Adventure World","PC","Disney Adventure World, est un parc à thèmes de la Walt Disney Company situé, en France, à 30 km de Paris, dans le secteur du Val d'Europe, à Marne-la-Vallée, en Seine-et-Marne. À proximité immédiate du parc Disneyland, de la gare TGV-RER de Marne-la-Vallée - Chessy et de Disney Village, il fait partie du complexe de loisirs Disneyland Paris géré par le groupe Euro Disney.",114,"fr:Disney_Adventure_World","https://upload.wikimedia.org/wikipedia/fr/thumb/d/d3/Disney_Adventure_World_Logo.jpg/330px-Disney_Adventure_World_Logo.jpg",{"cats":["disney","parcs"]}],["Q1229098",106,"parc","Disney California Adventure","PC","Disney California Adventure Park est un parc d'attractions de The Walt Disney Company situé à Anaheim, en Californie. Il ouvre ses portes le 8 février 2001, 46 ans après le premier Disneyland. Ce second parc du complexe Disneyland Resort se situe en face du premier et à côté de Downtown Disney District.","Disney California Adventure Park est un parc d'attractions de The Walt Disney Company situé à Anaheim, en Californie.","fr:Disney_California_Adventure","https://upload.wikimedia.org/wikipedia/fr/thumb/0/01/Logo_disney-DCA2010.JPG/330px-Logo_disney-DCA2010.JPG"],["Q420947",107,"parc","Disney Cruise Line","PC","Disney Cruise Line est une compagnie de croisière, filiale de la Walt Disney Company, née en 1995 quand la Walt Disney Company décida d'arrêter le contrat qu'elle avait avec Premier Cruises pour le segment maritime de ses offres de vacances. Elle fit construire deux bateaux par Fincantieri, constructeur naval en Italie: le Disney Magic et le Disney Wonder et acquit Castaway Cay, une île privée dans les Bahamas, désignée comme un port-étape exclusif pour ces navires.",118,"fr:Disney_Cruise_Line","c:f/fe/Disney_Cruise_Terminal%2C_Port_Canaveral%2C_March_2008.jpg"],["Q1431781",108,"parc","Disney Parks, Experiences and Products","PC","Walt Disney Parks, Experiences and Products, filiale de la Walt Disney Company, est l'une des quatre divisions de l'entreprise. Elle est créée en partie en 1952 pour la construction et la gestion de Disneyland mais réellement mise en service en 1971 sous le nom Walt Disney Attractions pour l'ouverture du second parc américain de Disney, Walt Disney World Resort. Certains logos ou documents officiels de Disney ajoutent parfois le terme « Theme », Walt Disney Theme Parks and Resorts.",113,"fr:Disney_Parks,_Experiences_and_Products","c:8/8d/Walt_Disney_World_Casting_Center.jpg"],["Q101008728",109,"parc","Disney Wish","C","Disney Wish est le cinquième navire de croisière détenu et exploité par Disney Cruise Line, une filiale de The Walt Disney Company. Il s'agit du plus grand navire de la flotte. Il est entré en service en juin 2022 et sera suivi par ses navires jumeaux, le Disney Treasure en 2024 et le Disney Destiny en 2025. Les quatre autres navires de la flotte sont le Disney Magic, le Disney Wonder, le Disney Dream et le Disney Fantasy.",115,"fr:Disney_Wish","https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Disney_Wish_Logo-Gold.svg/330px-Disney_Wish_Logo-Gold.svg.png"],["Q764186",110,"parc","Disney's Animal Kingdom","R","Disney's Animal Kingdom est un parc à thèmes zoologique de la Walt Disney Company situé à Bay Lake près de la ville d'Orlando. Le parc appartient au complexe de loisirs Walt Disney World, ouvert le 22 avril 1998, il s'agit du quatrième et dernier parc construit dans le complexe.",115,"fr:Disney's_Animal_Kingdom","https://upload.wikimedia.org/wikipedia/fr/thumb/4/42/Disney%27s_Animal_Kingdom_logo.svg/330px-Disney%27s_Animal_Kingdom_logo.svg.png",{"cats":["disney","parcs"]}],["Q1345090",111,"parc","Disney's Hollywood Studios","R","Disney's Hollywood Studios est un parc à thème de la Walt Disney Company situé à Bay Lake près de la ville d'Orlando. Le parc appartient au complexe de loisir Walt Disney World, ouvert le 1er mai 1989, il s'agit du troisième parc sur quatre construit dans le complexe. S'étendant sur 55 ha, le parc est dédié aux cinéma, à la télévision, à la musique et au théâtre tout rendant hommage à l'âge d'or des années 1930 à 1950 qu'a connu Hollywood.","Disney's Hollywood Studios est un parc à thème de la Walt Disney Company situé à Bay Lake près de la ville d'Orlando.","fr:Disney's_Hollywood_Studios","c:7/75/Stage_5_Sign.png",{"cats":["disney","parcs"]}],["Q181185",112,"parc","Disneyland","R","Disneyland, ou officiellement Disneyland Park, est un parc à thèmes situé dans la ville d'Anaheim, en Californie, aux États-Unis. Il est le seul « royaume enchanté » conçu et vu par Walt Disney et a été inauguré le 17 juillet 1955. Il fut construit en un peu plus d'un an par les équipes de Walt Disney Imagineering. Walt Disney dut pour le construire emprunter de l'argent en partie à ABC en échange de la production de la fameuse série Disneyland nommée par la suite Wonderful World of Walt Disney.",117,"fr:Disneyland","c:b/bd/Sleeping_Beauty_Castle_-_February_2024.png",{"cats":["disney","usa"]}],["Q2686174",113,"parc","Disneyland Hotel","C","Le Disneyland Hotel de Disneyland Paris est un hôtel de style victorien situé à l'entrée du parc Disneyland. Il compte 487 chambres dont 18 suites. Il est situé entre la gare de Main Street et les Fantasia Gardens, qui servent de jardins, de promenade et d'entrée au parc à thèmes.","Le Disneyland Hotel de Disneyland Paris est un hôtel de style victorien situé à l'entrée du parc Disneyland.","fr:Disneyland_Hotel_(Paris)","https://upload.wikimedia.org/wikipedia/fr/thumb/1/13/Disneyland_hotel_-_20150802_09h10_%2810644%29.jpg/330px-Disneyland_hotel_-_20150802_09h10_%2810644%29.jpg"],["Q206521",114,"parc","Disneyland Paris","L","Disneyland Paris, anciennement Euro Disney Resort puis Disneyland Resort Paris, est un complexe touristique et urbain de 22,30 km2 situé en sa majeure partie sur les communes de Chessy et Coupvray, à 32 km à l'est de Paris. Le complexe touristique, ouvert en 1992, comprend deux parcs à thèmes: le parc Disneyland et Disney Adventure World, ainsi que sept hôtels, tandis que le complexe urbain intensifie le tissu du secteur IV de Marne-la-Vallée au travers de Val d'Europe Agglomération.",117,"fr:Disneyland_Paris","https://upload.wikimedia.org/wikipedia/fr/thumb/6/6b/6270571962_8d7ed4725d_b_%281%29.jpg/330px-6270571962_8d7ed4725d_b_%281%29.jpg",{"cats":["disney","france","marques","parcs"]}],["Q964565",115,"parc","Dumbo the Flying Elephant","C","Dumbo the Flying Elephant est une célèbre attraction, de type manège, des parcs à thème Disney, de type Royaume Enchanté.",111,"fr:Dumbo_the_Flying_Elephant","https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Dumbo_the_Flying_Elephant_logo.svg/330px-Dumbo_the_Flying_Elephant_logo.svg.png"],["Q1052042",116,"parc","Epcot","L","Epcot est un parc à thèmes de Walt Disney World Resort situé près d'Orlando dans l'État de Floride aux États-Unis qui a ouvert le 1er octobre 1982. Ce nom provient de l'acronyme de Experimental Prototype Community Of Tomorrow, originellement EPCOT, qui est un projet de ville imaginé par Walt Disney dans les dernières années de sa vie.",119,"fr:Epcot","c:2/2b/Epcot_at_night.jpg",{"cats":["disney","parcs"]}],["Q1341067",117,"parc","Expedition Everest","C","Expedition Everest est une attraction unique de type montagnes russes située dans la section Asie de Disney's Animal Kingdom, quatrième parc à thèmes de Walt Disney World Resort.",116,"fr:Expedition_Everest","https://upload.wikimedia.org/wikipedia/fr/thumb/d/da/Expedition_Everest_logo.svg/330px-Expedition_Everest_logo.svg.png"],["Q2441096",118,"parc","Fantasyland","C","Fantasyland est l'un des cinq pays des Royaumes enchantés de Disney voulus par Walt Disney pour Disneyland. C'est le pays des contes de fées et de l'imaginaire. C'est aussi le pays situé dans le prolongement de Main Street, USA derrière le château, emblème et point central de chacun des parcs.","Fantasyland est l'un des cinq pays des Royaumes enchantés de Disney voulus par Walt Disney pour Disneyland.","fr:Fantasyland","https://upload.wikimedia.org/wikipedia/fr/thumb/5/53/Disneyland_Paris_Fantasyland_logo.png/330px-Disneyland_Paris_Fantasyland_logo.png"],["Q732575",119,"parc","Frontierland","C","Frontierland est l'un des pays des Royaumes enchantés de Disney. Il fait partie des cinq lands voulus par Walt Disney pour Disneyland.","Frontierland est l'un des pays des Royaumes enchantés de Disney.","fr:Frontierland","https://upload.wikimedia.org/wikipedia/fr/thumb/1/18/Disneyland_Paris_Frontierland_logo.png/330px-Disneyland_Paris_Frontierland_logo.png"],["Q605959",120,"parc","Hong Kong Disneyland","E","Hong Kong Disneyland est un parc à thème de la Walt Disney Company, qui a ouvert le 12 septembre 2005. Il est situé sur l'île de Lantau, à Hong Kong, en Chine.","Hong Kong Disneyland est un parc à thème de la Walt Disney Company, qui a ouvert le 12 septembre 2005.","fr:Hong_Kong_Disneyland","https://upload.wikimedia.org/wikipedia/en/thumb/7/7a/Hong_Kong_Disneyland_new_logo.png/330px-Hong_Kong_Disneyland_new_logo.png",{"cats":["disney","parcs"]}],["Q3150108",121,"parc","Indiana Jones Adventure","C","Indiana Jones Adventure est un terme désignant plusieurs attractions des parcs Disney. Le thème est centré sur le personnage d'Indiana Jones, mais Disney n'a réellement nommé Indiana Jones Adventure qu'une seule des différentes attractions, à savoir celle de Disneyland en Californie ouverte en 1995. Elle est toutefois sous titrée The Temple of the Forbidden Eye.","Indiana Jones Adventure est un terme désignant plusieurs attractions des parcs Disney.","fr:Indiana_Jones_Adventure","https://upload.wikimedia.org/wikipedia/en/thumb/8/89/Disneyland_Indiana_Jones_Attraction_Poster.jpg/330px-Disneyland_Indiana_Jones_Attraction_Poster.jpg"],["Q1571282",122,"parc","Indiana Jones et le Temple du Péril","C","Indiana Jones et le Temple du Péril, située au parc Disneyland Paris dans le land Adventureland, est une attraction de type montagnes russes avec looping unique, basées sur le thème de l'archéologie. Elle partage son concept avec Raging Spirits à Tokyo DisneySea mais sans le thème d'Indiana Jones.",118,"fr:Indiana_Jones_et_le_Temple_du_Péril","https://upload.wikimedia.org/wikipedia/fr/thumb/2/24/Logo_disney-IJTdP.jpg/330px-Logo_disney-IJTdP.jpg"],["Q285105",123,"parc","It's a Small World","R","It's a Small World, également typographié « it's a small world! », est une attraction de type croisière scénique célèbre des parcs à thèmes Disney. Elle représente les différents peuples et pays du monde au travers de poupées d'animaux et d'enfants en costumes locaux et de décors, le tout avec un fond musical joué en boucle et chanté en plusieurs langues. L'attraction célèbre la fraternité universelle.","It's a Small World, également typographié « it's a small world!","fr:It's_a_Small_World","https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/It%27s_a_Small_World_logo.svg/330px-It%27s_a_Small_World_logo.svg.png",{"cats":["disney","parcs"]}],["Q2611856",124,"parc","Mad Tea Party","C","Mad Hatter's Tea Cups ou Mad Tea Party est une célèbre attraction des parcs Disney.",null,"fr:Mad_Tea_Party","c:8/80/TeacupsMadTeaParty_wb.jpg"],["Q1324340",125,"parc","Magic Kingdom","R","Le Magic Kingdom, ou Royaume enchanté est le parc à thèmes construit à l'image de Disneyland pour Walt Disney World Resort. Il a été ouvert le 1er octobre 1971 à Orlando en Floride, à l'extrême nord du complexe de Walt Disney World Resort, au bout d'une autoroute privée de près de 10 kilomètres, la World Drive. Sa superficie de 43,3 hectares, située entre celle de Disneyland en Californie et celle de parc Disneyland en France, n'est pas utilisée dans sa totalité, principalement derrière Fantasyland.",115,"fr:Magic_Kingdom","https://upload.wikimedia.org/wikipedia/fr/thumb/0/06/Magic_Kingdom_logo.svg/330px-Magic_Kingdom_logo.svg.png",{"cats":["disney","parcs"]}],["Q2088399",126,"parc","Main Street, USA","C","Main Street, U.S.A. est la rue principale et la porte d'entrée des parcs à thèmes basés sur le concept de Disneyland, les Royaumes enchantés.","Main Street, U.S.A.","fr:Main_Street,_USA","c:2/2a/Disneyland_Main_Street.jpg"],["Q7100113",127,"parc","Orbitron","C","L'Orbitron est une voiture custom futuriste construite en 1964 par Ed « Big Daddy » Roth. Crue perdue, elle a été retrouvée au Mexique en 2007.","","en:Orbitron","c:3/3a/Orbitron_side.jpg"],["Q4827807",128,"parc","Pandora: The World of Avatar","C","Pandora: The World of Avatar est une zone thématique dans la partie sud-ouest du parc Disney's Animal Kingdom au Walt Disney World Resort, en Floride. Elle est inspirée de l'exolune fictive Pandora de la franchise cinématographique Avatar de James Cameron. Les principaux éléments qui caractérisent l'univers du film y sont reproduits: les montagnes flottantes, la faune et la flore, ainsi que le phénomène de bioluminescence.",117,"fr:Pandora:_The_World_of_Avatar","c:a/a5/Floating_Mountain_in_the_Valley_of_Mo%27ara_%2834346656636%29.jpg"],["Q2313567",129,"parc","Parc Disneyland","PC","Le parc Disneyland est un parc à thèmes de la Walt Disney Company situé en France, à Marne-la-Vallée en Seine-et-Marne, et qui a ouvert ses portes le 12 avril 1992. Il fait partie du complexe de loisirs Disneyland Paris, anciennement appelé Euro Disney Resort puis Disneyland Resort Paris. Le complexe appartient majoritairement à la Walt Disney Company via la société Euro Disney SCA à hauteur de 97,08 % des parts.",119,"fr:Parc_Disneyland_(Paris)","https://upload.wikimedia.org/wikipedia/fr/thumb/0/03/Parc_Disneyland_Paris_logo.png/330px-Parc_Disneyland_Paris_logo.png",{"cats":["disney","parcs"]}],["Q2916451",130,"parc","Peter Pan's Flight","C","Peter Pan's Flight est une attraction des parcs Disneyland, Magic Kingdom, Tokyo Disneyland, Parc Disneyland et Shanghai Disneyland. Située dans Fantasyland, elle existe depuis le début du parc. L'histoire présentée dans le parcours scénique vient du dessin animé Peter Pan réalisé en 1953 par Walt Disney Pictures.",111,"fr:Peter_Pan's_Flight","c:1/15/Dlp_peter_pan.jpg"],["Q2710077",131,"parc","Phantom Manor","C","Phantom Manor est une attraction de type parcours scénique située dans le parc Disneyland à Disneyland Paris. Il s'agit de la version européenne de l'attraction The Haunted Mansion, ancien concept du train fantôme revisité par Walt Disney et son équipe d'Imagineers. L'attraction est à la fois noire, humoristique, divertissante et particulièrement développée sur le plan esthétique.","Phantom Manor est une attraction de type parcours scénique située dans le parc Disneyland à Disneyland Paris.","fr:Phantom_Manor","https://upload.wikimedia.org/wikipedia/fr/thumb/4/40/Phantom_Manor.JPG/330px-Phantom_Manor.JPG"],["Q1713564",132,"parc","Pirates of the Caribbean","R","Pirates of the Caribbean est une des attractions les plus célèbres des parcs Disney. Elle a ouvert pour la première fois en 1967 à Disneyland et a été ensuite dupliquée dans la plupart des royaumes enchantés. L'attraction de Shanghaï Disneyland, nommée Pirates of the Caribbean: Battle for the Sunken Treasure utilise une technologie plus récente et un parcours reprenant plus d'éléments des films.","Pirates of the Caribbean est une des attractions les plus célèbres des parcs Disney.","fr:Pirates_of_the_Caribbean","c:d/db/Pirates_of_the_Caribbean.jpg",{"cats":["disney","parcs"]}],["Q7295489",133,"parc","Ratatouille : L'Aventure totalement toquée de Rémy","C","Ratatouille : L'Aventure totalement toquée de Rémy est une attraction de Disneyland Paris ouverte en 2014, où l'on est réduit à la taille d'un rat dans les cuisines de Gusteau.","","en:Remy's_Ratatouille_Adventure","https://upload.wikimedia.org/wikipedia/en/thumb/0/02/Ratatouille%2C_L%27Aventure_Totalement_Toqu%C3%A9e_de_R%C3%A9my.jpg/330px-Ratatouille%2C_L%27Aventure_Totalement_Toqu%C3%A9e_de_R%C3%A9my.jpg",{"cats":["disney","parcs"]}],["Q865312",134,"parc","Shanghai Disneyland","R","Shanghai Disneyland est un parc à thèmes de la Walt Disney Company, de 90 hectares, ouvert le 16 juin 2016. Il est situé dans la ville nouvelle de Chuansha, dans le district de Pudong, à Shanghai, en Chine. Il est le deuxième parc Disney à ouvrir dans le pays après le Hong Kong Disneyland dont l'ouverture date de 2005. Le parc d'attraction forme avec le Toy-Story Hotel et le Shanghai Disneyland Hotel, le complexe Shanghai Disney Resort.","Shanghai Disneyland est un parc à thèmes de la Walt Disney Company, de 90 hectares, ouvert le 16 juin 2016.","fr:Shanghai_Disneyland","https://upload.wikimedia.org/wikipedia/en/thumb/b/bd/ShanghaiDisneyland.svg/330px-ShanghaiDisneyland.svg.png",{"cats":["disney","parcs"]}],["Q2775778",135,"parc","Soarin'","C","Soarin' est une attraction de type flying theater implantée à Disney California Adventure, à Epcot, à Shanghai Disneyland et à Tokyo DisneySea.",110,"fr:Soarin'","https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Soarin%27_Logo.svg/330px-Soarin%27_Logo.svg.png"],["Q2306380",136,"parc","Space Mountain","PC","Space Mountain est une attraction des parcs Disney de type montagnes russes enfermées. Elle est présente dans la plupart des Royaumes enchantés, dans les zones thématiques Tomorrowland et Discoveryland.","Space Mountain est une attraction des parcs Disney de type montagnes russes enfermées.","fr:Space_Mountain","c:b/b8/Space_Mountain_%2822134458542%29.jpg",{"cats":["disney","parcs"]}],["Q2916749",137,"parc","Spaceship Earth","C","Spaceship Earth est un pavillon-attraction du parc Epcot de Walt Disney World Resort. La géode de 18 étages abrite un parcours scénique en Omnimover de plus de 13 minutes qui explore l'histoire de la communication entre les hommes depuis l'homme des cavernes jusqu'à Internet. C'est le symbole principal du parc.","Spaceship Earth est un pavillon-attraction du parc Epcot de Walt Disney World Resort.","fr:Spaceship_Earth","c:7/7a/Spaceship_Earth_2.jpg"],["Q2492971",138,"parc","Splash Mountain","PC","Splash Mountain est une attraction des parcs Disney. C'est la première attraction de Disney reprenant un classique des autres parcs d'attractions, la rivière en tronc avec chute. Disney a revu le concept pour en faire une attraction de « haute qualité » avec une grande précision de détail.","Splash Mountain est une attraction des parcs Disney.","fr:Splash_Mountain","c:c/c8/Splash_Mountain%2C_Tokyo_Disneyland_%289409908130%29.jpg"],["Q2251688",139,"parc","Star Tours","C","Star Tours est une ancienne attraction des parcs Disney de type cinéma dynamique. Conçue par les équipes de la WED Enterprises et de Lucasfilm sous la direction de George Lucas, il s'agit d'un simulateur de vol permettant aux visiteurs de voyager dans l'univers de la saga Star Wars. À son ouverture, elle est considérée comme faisant partie des meilleures attractions des parcs Disney.","Star Tours est une ancienne attraction des parcs Disney de type cinéma dynamique.","fr:Star_Tours","https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Star_Tours_logo.svg/330px-Star_Tours_logo.svg.png"],["Q22078132",140,"parc","Star Wars: Galaxy's Edge","PC","Star Wars: Galaxy's Edge est une zone thématique des parcs Disneyland en Californie et Disney's Hollywood Studios au Walt Disney World Resort en Floride. Elle est centrée sur la franchise cinématographique Star Wars de George Lucas. Se déroulant sur la planète Batuu, les éléments iconiques de la saga y sont reproduits.",116,"fr:Star_Wars:_Galaxy's_Edge","https://upload.wikimedia.org/wikipedia/fr/thumb/9/9a/Star-wars-galaxys-edge.jpg/330px-Star-wars-galaxys-edge.jpg",{"cats":["disney","parcs"]}],["Q1776103",141,"parc","The Twilight Zone Tower of Terror","E","The Twilight Zone Tower of Terror, plus couramment appelé Tower of Terror ou la Tour de la Terreur en français, est un parcours scénique des parcs Disney s'inspirant du principe des tours de chute mais utilisant la technologie des ascenseurs. À la différence des chutes libres classiques qui ne sont pas accélérées, cette attraction est basée sur le système hyper drop ou ejector, qui provoque des accélérations verticales supérieures à l'accélération de la pesanteur terrestre.",118,"fr:The_Twilight_Zone_Tower_of_Terror","https://upload.wikimedia.org/wikipedia/fr/thumb/2/24/Logo_disney-TowerofTerror.jpg/330px-Logo_disney-TowerofTerror.jpg",{"cats":["disney","parcs"]}],["Q1202341",142,"parc","Tokyo DisneySea","E","Tokyo DisneySea est le second parc à thème ouvert le 4 septembre 2001 au sein du Tokyo Disney Resort. Situé au sud de Tokyo Disneyland, on peut rejoindre le parc en empruntant la Disney Resort Line. Ce parc à thème permet d'élargir l'offre du complexe et de le transformer comme les autres domaines Disney en un « resort ».","Tokyo DisneySea est le second parc à thème ouvert le 4 septembre 2001 au sein du Tokyo Disney Resort.","fr:Tokyo_DisneySea","https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Tokyo_DisneySea_logo.svg/330px-Tokyo_DisneySea_logo.svg.png",{"cats":["disney","parcs"]}],["Q1102604",143,"parc","Toy Story Land","C","Toy Story Land ou Toy Story Playland sont des zones thématiques des parcs Disney, axées sur l'univers des films Toy Story.",115,"fr:Toy_Story_Land","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Toy_Story_Land_logo.svg/330px-Toy_Story_Land_logo.svg.png"],["Q3538315",144,"parc","Tree of Life","C","L'Arbre de vie est le symbole du parc Disney's Animal Kingdom, c'est une sous-espèce géante de Disneyodendron. Il est présent dans le parc depuis son ouverture le 22 avril 1998.","L'Arbre de vie est le symbole du parc Disney's Animal Kingdom, c'est une sous-espèce géante de Disneyodendron.","fr:Tree_of_Life_(Disney's_Animal_Kingdom)","c:6/66/-ARBOL_DE_LA_VIDA-TREE_OF_LIFE-DISNEY_ANIMAL_KINGDOM_-_panoramio.jpg"],["Q434841",145,"studio","20th Century Studios","E","20th Century Studios est une société américaine de productions cinématographiques appartenant à la Walt Disney Company depuis 2019. Elle a pour origine la Fox Film créée en 1915 par William Fox, qui fusionne ensuite avec Twentieth Century Pictures, créée en 1933 par Darryl F. Zanuck et Joseph Schenck, l'ancien président de United Artists), pour former en 1935, la Twentieth Century Fox.",118,"fr:20th_Century_Studios","https://upload.wikimedia.org/wikipedia/fr/thumb/5/5e/20th_Century_Studios.svg/330px-20th_Century_Studios.svg.png"],["Q1326000",146,"studio","A Whole New World","C","A Whole New World est une chanson américaine de Lea Salonga et Brad Kane composée par Alan Menken et Tim Rice, extraite de la bande originale du film Aladdin et sortie en 1992. Cette version ne rentre pas dans les hit-parades, à la différence de la version de Peabo Bryson et Regina Belle, qui se classe no 1 au Billboard Hot 100 et au Hot Adult Contemporary Tracks puis reçoit le Golden Globe de la meilleure chanson originale et l'Oscar de la meilleure chanson originale en 1993 puis le Grammy Award de la chanson de…",119,"fr:A_Whole_New_World",""],["Q317272",147,"studio","Alan Menken","R","Alan Menken est un compositeur américain né le 22 juillet 1949 à New Rochelle. Il est mondialement connu pour ses nombreuses collaborations avec les studios Disney sur de nombreux films d'animations à succès comme La Petite Sirène, Aladdin ou La Belle et la Bête.","Alan Menken est un compositeur américain né le 22 juillet 1949 à New Rochelle.","fr:Alan_Menken","c:b/be/Alan_Menken_2013.jpg"],["Q55603855",148,"studio","Amphibia","PC","Amphibia est une série télévisée d'animation américaine créée par Matt Braly, produite par Disney Television Animation et diffusée du 17 juin 2019 au 14 mai 2022 sur Disney Channel. Le premier épisode a été mis en ligne sur DisneyNow et YouTube le 14 juin 2019.",118,"fr:Amphibia_(série_télévisée_d'animation)","c:8/85/Amphibia_color_logo.png"],["Q328723",149,"studio","Andrew Stanton","R","Andrew Stanton est un acteur, scénariste, réalisateur, animateur et producteur américain né le 3 décembre 1965 à Boston au Massachusetts. Chez les studios Pixar, il est connu pour être le scénariste des cinq Toy Story, et également pour la réalisation de Le Monde de Nemo et WALL-E.",119,"fr:Andrew_Stanton","c:b/bc/Andrew_Stanton_at_the_2026_Sundance_Film_Festival_for_In_the_Blink_of_an_Eye_%2801%29_%28cropped%29.jpg"],["Q55070849",150,"studio","Bao","C","Bao est un court métrage d'animation américain produit par Pixar et réalisé par Domee Shi, une animatrice de Toronto, qui est la toute première femme à réaliser un court métrage pour cette société. En France, il est sorti en première partie de Les Indestructibles 2 le 15 juin 2018.",117,"fr:Bao_(court_métrage)","https://upload.wikimedia.org/wikipedia/fr/thumb/1/1a/Bao_logo.png/330px-Bao_logo.png"],["Q848923",151,"studio","Bibbidi-Bobbidi-Boo","C","Bibbidi-Bobbidi-Boo est une chanson écrite et composée par Mack David, Al Hoffman et Jerry Livingston pour le long-métrage Disney Cendrillon.",109,"fr:Bibbidi-Bobbidi-Boo",""],["Q86408516",152,"studio","Bob Chapek","PC","Robert « Bob » Chapek, né le 21 août 1960, est un homme d'affaires américain, qui fut notamment président-directeur général de la Walt Disney Company de 2020 à 2022. Avant de devenir PDG le 25 février 2020, il était responsable de la filiale Walt Disney Parks and Resorts de la société.",115,"fr:Bob_Chapek","c:7/70/Bob_Chapek_%2849607223226%29_%28cropped%29.jpg"],["Q310960",153,"studio","Brad Bird","E","Philip Bradley Bird, dit Brad Bird, est un animateur, réalisateur, scénariste et producteur de cinéma américain, né le 24 septembre 1957 à Kalispell au Montana.",118,"fr:Brad_Bird","c:b/b6/Brad_Bird_2018.jpg"],["Q2930303",154,"studio","C'est la fête","C","C'est la fête est une chanson issue du long métrage de 1991, La Belle et la Bête.",null,"fr:C'est_la_fête_(chanson_Disney)",""],["Q217250",155,"studio","Camp Rock","PC","Camp Rock est un téléfilm américain de la collection des Disney Channel Original Movie réalisé par Matthew Diamond et diffusé le 20 juin 2008 sur Disney Channel.",117,"fr:Camp_Rock","https://upload.wikimedia.org/wikipedia/fr/thumb/1/1d/Camp_Rock_Logo.png/330px-Camp_Rock_Logo.png",{"cats":["disney","enfance"]}],["Q1031911",156,"studio","Can You Feel the Love Tonight","C","Can You Feel the Love Tonight est une chanson composée par Elton John sur des paroles de Tim Rice pour le long métrage d'animation Le Roi lion.",118,"fr:Can_You_Feel_the_Love_Tonight","https://upload.wikimedia.org/wikipedia/en/thumb/3/35/Elton_john-can_you_feel_the_love_tonight_s_1.jpg/330px-Elton_john-can_you_feel_the_love_tonight_s_1.jpg"],["Q1820189",157,"studio","Chim Chim Cher-ee","C","Chim Chim Cher-ee ou Chim Chim Chimney est une célèbre musique de film, écrite et composée par les frères Sherman, pour le film musical américain Mary Poppins, de Robert Stevenson de Walt Disney Pictures de 1964 (adapté du roman Mary Poppins de Pamela L. Travers de 1934). Elle remporte l'Oscar de la meilleure chanson originale 1965.",119,"fr:Chim_Chim_Cher-ee",""],["Q390223",158,"studio","Club Penguin","PC","Club Penguin était un jeu en ligne massivement multijoueur grand public lancé en octobre 2005 et disparu en mars 2017. Le joueur y incarnait un manchot sur une île enneigée, pouvant s'y déplacer et interagir avec les autres joueurs à travers des discussions ou des mini-jeux. Le jeu adoptait un modèle free-to-play, intégrant des éléments cosmétiques payants.","Club Penguin était un jeu en ligne massivement multijoueur grand public lancé en octobre 2005 et disparu en mars 2017.","fr:Club_Penguin","c:7/78/Club_Penguin_Logo_2012_-_2017.png",{"cats":["disney","web","enfance"]}],["Q5965889",159,"studio","Comme un homme","C","Comme un homme est une chanson provenant du 54e long métrage d'animation des studios Disney, Mulan, sorti en 1998. Les paroles de la version originale ont été écrites par David Zippel et la musique a été composée par Matthew Wilder. Dans le film, la chanson est interprétée par le capitaine Li Shang, qui dans la version originale, est incarné par le chanteur américain Donny Osmond, la version française est elle adaptée par Luc Aulivier et est chantée par Patrick Fiori.","Comme un homme est une chanson provenant du 54e long métrage d'animation des studios Disney, Mulan, sorti en 1998.","fr:Comme_un_homme_(chanson)",""],["Q77565091",160,"studio","Dans un autre monde","C","Dans un autre monde, Into The Unknown en version originale, est une chanson interprétée par Idina Menzel et Aurora pour le film d'animation La Reine des neiges 2. La musique et les paroles ont été composées par Kristen Anderson-Lopez et Robert Lopez.",119,"fr:Dans_un_autre_monde_(La_Reine_des_neiges_2)",""],["Q1458430",161,"studio","Des arbres et des fleurs","C","Des arbres et des fleurs ou Des fleurs et des arbres est le premier dessin animé en couleurs de la série Silly Symphonies, réalisé par Burt Gillett, produit par Walt Disney et sorti le 30 juillet 1932.",110,"fr:Des_arbres_et_des_fleurs","c:0/0a/Flowers_and_Trees_Title_Card.png"],["Q17278086",162,"studio","Descendants","R","Descendants est un téléfilm américain de la collection des Disney Channel Original Movie réalisé par Kenny Ortega et diffusé le 31 juillet 2015 sur Disney Channel.",116,"fr:Descendants_(téléfilm)","https://upload.wikimedia.org/wikipedia/fr/thumb/9/9f/Descendants_Logo.png/330px-Descendants_Logo.png"],["Q178837",163,"studio","Disney Channel","R","Disney Channel est une chaîne de télévision américaine appartenant à la Walt Disney Company. Ce sont des chaînes destinées aux enfants mais aussi à la famille. Elles dépendent toutes de Walt Disney Television et ont une programmation qui « essaye d'être la gardienne des valeurs familiales ». Toutefois elles n'appartiennent pas obligatoirement à la société Walt Disney Television.","Disney Channel est une chaîne de télévision américaine appartenant à la Walt Disney Company.","fr:Disney_Channel","c:e/eb/Disney_Channel_HQ.jpg",{"cats":["disney","enfance"]}],["Q111828779",164,"studio","Disney Dreamlight Valley","PC","Disney Dreamlight Valley est un jeu vidéo édité par Gameloft et développé par le studio interne Gameloft Montréal. Il est sorti en accès anticipé le 6 septembre 2022, tandis que le jeu complet est disponible le 5 décembre 2023 sur Windows et sur les consoles PlayStation 4, PlayStation 5, Nintendo Switch, Xbox One et Xbox Series.","Disney Dreamlight Valley est un jeu vidéo édité par Gameloft et développé par le studio interne Gameloft Montréal.","fr:Disney_Dreamlight_Valley","https://upload.wikimedia.org/wikipedia/fr/thumb/2/24/Disney_Dreamlight_Valley_Logo.svg/330px-Disney_Dreamlight_Valley_Logo.svg.png"],["Q2734172",165,"studio","Disney Fairies","C","Disney Fairies est une franchise de la Walt Disney Company. Le principe de cette gamme transversale de Disney Consumer Products est de capitaliser sur le riche héritage des contes de fées au sein de l'univers de Disney. Le personnage principal est la Fée Clochette de Peter Pan, mais elle sert de fil conducteur pour un ensemble d'éléments, principalement à l'attention des jeunes filles, lié au monde magique des fées et de la fantasy.","Disney Fairies est une franchise de la Walt Disney Company.","fr:Disney_Fairies","https://upload.wikimedia.org/wikipedia/fr/thumb/a/a4/Logo_DisneyFairies2.png/330px-Logo_DisneyFairies2.png"],["Q19861435",166,"studio","Disney Infinity","C","Disney Infinity est une série de jeux vidéo de plates-formes et d'aventure de type monde virtuel libre associé à des figurines, développé par Avalanche Software et édité par Disney Interactive Studios. La série reprend le principe lancé par Skylanders d'Activision Blizzard en le transposant dans les univers Disney-Pixar, Marvel et Star Wars. Elle débute le 18 août 2013 avec la sortie de Disney Infinity sur PlayStation 3, Wii, Wii U, Xbox 360, Nintendo 3DS, iOS et Microsoft Windows.",116,"fr:Disney_Infinity","https://upload.wikimedia.org/wikipedia/fr/thumb/e/e3/Disney_Infinity_Logo.jpg/330px-Disney_Infinity_Logo.jpg"],["Q1150306",167,"studio","Disney Legends","C","Disney Legends est un programme lancé en 1987 par la Walt Disney Company pour récompenser les hommes et les femmes qui ont contribué de manière émérite à l'entreprise. Il s'agit du temple de la renommée de la firme. Les décorations sont décernées et remises chaque année lors d'une cérémonie spéciale.",118,"fr:Disney_Legends","c:9/98/Jon_Favreau_2019_Disney_Legends_Awards_Ceremony_D23_EXPO_2019_%2851440497171%29.jpg"],["Q3030504",168,"studio","Disney on Ice","C","Disney on Ice ou World on Ice sont les noms de plusieurs spectacles sur glace donnés par la société Feld Entertainment aux États-Unis et diverses sociétés dans les autres pays sous licence de la Walt Disney Company. Les spectacles sont principalement destinés à un public jeune et comprennent des patineurs en costume de personnages Disney exécutant des figures sur une musique empruntée aux films Disney.",118,"fr:Disney_on_Ice","c:a/a9/Disney_on_Ice_2017_-_Hartwall_Arena%2C_Helsinki.jpg"],["Q5282482",169,"studio","Disney Vault","C","Le « Disney Vault » (coffre Disney) désignait la pratique de Disney de retirer régulièrement ses classiques de la vente en vidéo pour créer la rareté.","","en:Disney_Vault",""],["Q54958752",170,"studio","Disney+","E","Disney+ est un service de vidéo à la demande par abonnement payant détenu et exploité par le groupe américain The Walt Disney Company, au travers de sa division Walt Disney Direct-to-Consumer and International, lancé en novembre 2019 en Amérique du Nord.",118,"fr:Disney+","https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Disney%2B_2024.svg/330px-Disney%2B_2024.svg.png",{"cats":["disney","web"]}],["Q114632",171,"studio","Docteur La Peluche","PC","Docteur La Peluche est une série télévisée d'animation américaine en 136 épisodes de 22 minutes produite par Disney Enterprise et Brown Bag Films et diffusée du 23 mars 2012 au 18 avril 2020 sur Disney Channel et Disney Junior.",115,"fr:Docteur_La_Peluche","https://upload.wikimedia.org/wikipedia/en/thumb/1/15/Doc_McStuffins_logo.png/330px-Doc_McStuffins_logo.png"],["Q24574641",172,"studio","Elena d'Avalor","PC","Elena d'Avalor est une série télévisée d'animation 3D américaine en 77 épisodes de 24 minutes créée par Craig Gerber diffusée du 22 juillet 2016 au 23 août 2020 sur Disney Channel et en simultané sur Disney Channel Canada au Canada. Elle tire son origine de la série d'animation Princesse Sofia diffusée sur Disney Junior.",116,"fr:Elena_d'Avalor","https://upload.wikimedia.org/wikipedia/fr/thumb/5/5b/Logo_Elena_d%27Avalor.png/330px-Logo_Elena_d%27Avalor.png"],["Q573760",173,"studio","Epic Mickey","PC","Epic Mickey est un jeu vidéo de type action-aventure et plates-formes sorti sur Wii le 25 novembre 2010, reprenant l'univers Disney.",114,"fr:Epic_Mickey","https://upload.wikimedia.org/wikipedia/en/thumb/5/59/Epic_Mickey.jpg/330px-Epic_Mickey.jpg"],["Q217776",174,"studio","ESPN","R","ESPN est une chaîne de télévision sportive américaine, créée en 1979, à l'origine du groupe de télévision ESPN Inc, filiale depuis 1996 de la Walt Disney Company et de la Hearst Corporation.",115,"fr:ESPN_(chaîne_de_télévision)",""],["Q17005728",175,"studio","Je suis ton meilleur ami","C","« Je suis ton meilleur ami » (Friend Like Me) est la chanson du Génie dans Aladdin (Disney, 1992), interprétée en VO par Robin Williams.","","en:Friend_Like_Me",""],["Q30597506",176,"studio","Frozen","C","Frozen: The Broadway Musical, ou simplement Frozen, est un spectacle musical produit par Walt Disney Theatrical Productions avec musique et paroles de Kristen Anderson-Lopez et Robert Lopez et un livret de Jennifer Lee. Il est basé sur le film La Reine des neiges et la franchise du même nom.",111,"fr:Frozen_(comédie_musicale)","c:5/59/St_James_Theatre_-_Frozen_%2848296062327%29.jpg"],["Q937172",177,"studio","Gargoyles, les anges de la nuit","PC","Gargoyles, les anges de la nuit est une série télévisée d'animation américaine en 78 épisodes de 25 minutes, produite par les studios Disney et diffusée à partir du 24 octobre 1994 en syndication pour la première et deuxième saisons, tandis que pour sa troisième saison elle a déménagé sur le réseau ABC et s'est terminée le 15 février 1997. La syndication s'est arrêtée le 29 août 1997.",117,"fr:Gargoyles,_les_anges_de_la_nuit","https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Gargoyles_1994_logo.svg/330px-Gargoyles_1994_logo.svg.png"],["Q1382544",178,"studio","Glen Keane","C","Glen Keane est un animateur, réalisateur et scénariste américain né le 13 avril 1954 à Philadelphie en Pennsylvanie. Il travaille principalement pour le studio Walt Disney Pictures où il crée et anime des personnages comme la Bête, Ariel, Tarzan ou encore Raiponce. Ayant travaillé 38 ans pour Walt Disney Animation Studios, il démissionne pour trouver de nouvelles voies d’exploration.","Glen Keane est un animateur, réalisateur et scénariste américain né le 13 avril 1954 à Philadelphie en Pennsylvanie.","fr:Glen_Keane","c:0/0e/GlenKeaneHeadshotColor.jpg"],["Q5575044",179,"studio","Go the Distance","C","Go the Distance est une chanson de Roger Bart composée par Alan Menken et David Zippel, extraite de la bande originale du film Hercule et sortie en 1997. Le chanteur américain Michael Bolton enregistre une version pop de la chanson pour le générique du film. Dans la version espagnole, la chanson est interprétée par Ricky Martin, à la fois dans le film et pour le générique.",118,"fr:Go_the_Distance",""],["Q1646614",180,"studio","Hakuna Matata","C","Hakuna Matata est une chanson composée par Elton John, avec les paroles de Tim Rice, pour le long-métrage d'animation de Disney Le Roi lion, sorti en 1994.",117,"fr:Hakuna_Matata_(chanson)",""],["Q1334295",181,"studio","Howard Ashman","PC","Howard Ashman est un parolier, librettiste et metteur en scène américain né le 3 mai 1950 à Baltimore et mort le 14 mars 1991 à New York.",115,"fr:Howard_Ashman","c:3/3b/Howard_Ashman_on_set_of_Little_Shop_of_Horrors_%28cropped%29.webp"],["Q2257959",182,"studio","Je voudrais déjà être roi","C","« Je voudrais déjà être roi » est une chanson du Roi lion (1994), écrite par Elton John et Tim Rice, où le jeune Simba rêve de son règne.","","en:I_Just_Can't_Wait_to_Be_King",""],["Q201852",183,"studio","Il en faut peu pour être heureux","C","Il en faut peu pour être heureux est une chanson composée par Terry Gilkyson pour le long métrage d'animation Le Livre de la jungle produit par les studios Disney.",118,"fr:Il_en_faut_peu_pour_être_heureux","c:e/e7/Fanfare_%C3%A0_la_manifestation_du_8_mars_2025_%C3%A0_Paris_%283%29.webm"],["Q269214",184,"studio","John Lasseter","R","John Lasseter, né le 12 janvier 1957 à Los Angeles, est un réalisateur et producteur américain de films d'animation. Il était directeur artistique de Pixar Animation Studios et de Walt Disney Animation Studios ainsi que conseiller artistique de Walt Disney Imagineering.","John Lasseter, né le 12 janvier 1957 à Los Angeles, est un réalisateur et producteur américain de films d'animation.","fr:John_Lasseter","c:b/b0/JohnLasseterOct2011.jpg"],["Q1110226",185,"studio","Embrasse-la","C","« Embrasse-la » (Kiss the Girl) est une chanson de La Petite Sirène (Disney, 1989) où Sébastien le crabe pousse Éric à embrasser Ariel.","","en:Kiss_the_Girl",""],["Q2028257",186,"studio","L'Air du vent","C","L'Air du vent est une chanson composée par Alan Menken pour le long métrage d'animation de 1995 Pocahontas produit par Walt Disney Pictures. Le titre original en anglais est Colors of the Wind, la version québécoise est intitulée Les Couleurs du vent.",118,"fr:L'Air_du_vent",""],["Q344081",187,"studio","La Cour de récré","R","La Cour de récré est une série télévisée d'animation américaine en 65 épisodes de 22 minutes créée par Paul Germain et Joe Ansolabehere, produite par Disney Television Animation, et diffusée entre le 31 août 1997 et le 5 novembre 2001 dans le bloc de programmes Disney's One Saturday Morning sur le réseau ABC pour les trois premières saisons, puis sur le réseau UPN.",118,"fr:La_Cour_de_récré","https://upload.wikimedia.org/wikipedia/fr/thumb/1/1b/Recess_Logo.jpg/330px-Recess_Logo.jpg",{"cats":["disney","persos_anim"]}],["Q494748",188,"studio","La Maison de Mickey","PC","La Maison de Mickey est une série télévisée d'animation américaine en 108 épisodes de 23 minutes, 4 épisodes de 49 minutes, 8 épisodes de 30 minutes, 1 épisode de 53 minutes, 2 épisodes de 45 minutes, 1 épisode de 47 minutes, 1 épisode de 44 minutes et 1 épisode de 46 minutes créée par Bobs Gannaway et diffusée entre le 5 mai 2006 et le 6 novembre 2016, d'abord sur Playhouse Disney jusqu'en 2011, puis sur Disney Junior.",114,"fr:La_Maison_de_Mickey","https://upload.wikimedia.org/wikipedia/fr/thumb/3/3d/La_maison_de_Mickey.png/330px-La_maison_de_Mickey.png"],["Q28312308",189,"studio","Le Bleu Lumière","C","« Le Bleu Lumière » est la chanson phare de Vaiana (Disney, 2016), écrite par Lin-Manuel Miranda, où l'héroïne rêve de partir sur l'océan.","","en:How_Far_I'll_Go",""],["Q3223729",190,"studio","Le Journal de Mickey","C","Le Journal de Mickey ou JDM est un magazine bimensuel français de bande dessinée publié depuis le 21 octobre 1934. La publication est interrompue entre 1944 et 1952 puis reprend la numérotation à zéro. Réputé pour être le premier magazine en France à s'appuyer sur les personnages Disney, il est aussi le plus ancien magazine français destiné à la jeunesse encore en activité. Il est réédité dans des albums, qui regroupent à chaque fois plusieurs numéros.","Le Journal de Mickey ou JDM est un magazine bimensuel français de bande dessinée publié depuis le 21 octobre 1934.","fr:Le_Journal_de_Mickey","https://upload.wikimedia.org/wikipedia/fr/thumb/6/69/Logo_Le_Journal_de_Mickey.jpg/330px-Logo_Le_Journal_de_Mickey.jpg"],["Q1195106",191,"studio","Le Roi lion, la comédie musicale","PC","Le Roi Lion est une comédie musicale américaine de Roger Allers et Irene Mecchi, avec des paroles de Tim Rice et une musique d'Elton John, inspirée du film homonyme des studios Disney et créée le 8 juillet 1997 à l'Orpheum Theatre de Minneapolis.",116,"fr:Le_Roi_lion_(comédie_musicale)","https://upload.wikimedia.org/wikipedia/fr/thumb/8/84/Le_Roi_lion_%28com%C3%A9die_musicale%29_Logo.png/330px-Le_Roi_lion_%28com%C3%A9die_musicale%29_Logo.png"],["Q1217867",192,"studio","Le Vieux Moulin","C","Le Vieux Moulin est un court métrage d'animation américain de la série des Silly Symphonies, réalisé par Wilfred Jackson et Graham Heid, produit par Walt Disney pour RKO Radio Pictures, et sorti le 5 novembre 1937.",112,"fr:Le_Vieux_Moulin","https://upload.wikimedia.org/wikipedia/en/thumb/d/da/The_Old_Mill_poster.jpg/330px-The_Old_Mill_poster.jpg"],["Q380920",193,"studio","Lee Unkrich","C","Lee Unkrich, né Lee Edward Unkrich le 8 août 1967 à Cleveland, Ohio, est un réalisateur, monteur et scénariste américain connu pour avoir contribué au succès de nombreux films des studios Pixar. Réalisateur avec Adrian Molina sur Coco, réalisateur sur Toy Story 3, co-auteur de l’histoire sur ces deux films, il a gagné l’Oscar du meilleur film d’animation pour chacun d’eux.",110,"fr:Lee_Unkrich","c:0/05/Lee_Unkrich_cropped_2009.jpg"],["Q27645779",194,"studio","Les Green à Big City","R","Les Green à Big City est une série d'animation américaine créée par The Houghton Brothers et diffusée depuis le 18 juin 2018 sur Disney Channel.",119,"fr:Les_Green_à_Big_City","c:b/b1/Big_City_Greens_French_Logo.png"],["Q1218152",195,"studio","Les Trois Petits Cochons","C","Les Trois Petits Cochons est un court métrage d'animation américain de la série Silly Symphonies réalisé par Burton Gillett et produit par les studios Disney en 1933. Il est basé sur le conte folklorique Les Trois Petits Cochons.",115,"fr:Les_Trois_Petits_Cochons_(film)","https://upload.wikimedia.org/wikipedia/en/thumb/a/a5/Three_Little_Pigs_poster.jpg/330px-Three_Little_Pigs_poster.jpg"],["Q635717",196,"studio","Lizzie McGuire","R","Lizzie McGuire est une série télévisée américaine en 65 épisodes de 22-24 minutes, créée par Terri Minsky et diffusée entre le 12 janvier 2001 et le 14 février 2004 sur Disney Channel.",117,"fr:Lizzie_McGuire","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Lizzie_McGuire_logo.svg/330px-Lizzie_McGuire_logo.svg.png",{"cats":["disney","enfance"]}],["Q242446",197,"studio","Lucasfilm","R","Lucasfilm Limited est une société de production de cinéma et de télévision américaine, créée par George Lucas en 1971. Parmi les films qui ont été produits par Lucasfilm, les plus célèbres sont les sagas Star Wars et Indiana Jones. La société a été rachetée le 30 octobre 2012 par The Walt Disney Company.","Lucasfilm Limited est une société de production de cinéma et de télévision américaine, créée par George Lucas en 1971.","fr:Lucasfilm","c:8/86/Letterman_Digital_Arts_Center%2C_Building_B_%28side_view%29.jpg"],["Q914155",198,"studio","Luxo Jr.","C","Luxo Jr. est le premier court métrage de Pixar, sorti en 1986 lorsque le studio d'animation venait juste d'être créé. D'une durée de deux minutes trente, le film était la vitrine de la société afin de démontrer le savoir-faire des créateurs en matière d'images de synthèses, notamment dans les effets d'ombres.","Luxo Jr.","fr:Luxo_Jr.","https://upload.wikimedia.org/wikipedia/fr/thumb/e/e2/Luxo_Jr..png/330px-Luxo_Jr..png"],["Q55635444",199,"studio","Luz à Osville","R","Luz à Osville est une série télévisée d’animation américaine créée par Dana Terrace et produite par Disney Television Animation. La série est diffusée entre le 10 janvier 2020 et le 8 avril 2023 sur Disney Channel. En novembre 2019, la série a été renouvelée pour une deuxième saison avant même le début de la diffusion de la première saison. En mai 2021, la série est renouvelée pour une troisième saison avant même le début de la diffusion de la deuxième saison.",117,"fr:Luz_à_Osville","https://upload.wikimedia.org/wikipedia/fr/thumb/1/18/Luz_%C3%A0_Osville_logo.png/330px-Luz_%C3%A0_Osville_logo.png"],["Q367466",200,"studio","Marvel Studios","R","Marvel Studios est une société de production cinématographique américaine en prises de vue réelles et en animation assurant les adaptations cinématographiques des productions de Marvel Entertainment, essentiellement issues des Marvel Comics.",114,"fr:Marvel_Studios","c:d/de/Frankgwellsbuilding.JPG"],["Q2210892",201,"studio","Mary Poppins, la comédie musicale","C","Mary Poppins est une comédie musicale américano-britannique coproduite par Walt Disney Theatrical Productions et Cameron Mackintosh, adaptée du film éponyme des studios Disney sorti en 1964 et de la série de livres pour enfants de Pamela L. Travers.",112,"fr:Mary_Poppins_(comédie_musicale)","https://upload.wikimedia.org/wikipedia/fr/thumb/d/d5/Mary_Poppins_%28com%C3%A9die_musicale%29_Logo.png/330px-Mary_Poppins_%28com%C3%A9die_musicale%29_Logo.png"],["Q727953",202,"studio","Michael Eisner","R","Michael Dammann Eisner est né le 7 mars 1942 à Mount Kisco, État de New York. Il fut à la tête de la Walt Disney Company de 1984 à 2005. Il a aussi fondé l'organisation philanthropique Eisner Foundation, dirigée par sa femme, Jane Breckenridge. Il était la 891e fortune mondiale en 2007. Il est le père de trois garçons: Breck, Eric et Anders.","Michael Dammann Eisner est né le 7 mars 1942 à Mount Kisco, État de New York.","fr:Michael_Eisner","c:6/60/MichaelEisnerOct10.jpg"],["Q383914",203,"studio","Myster Mask","PC","Myster Mask est une série télévisée d'animation américaine en 91 épisodes de 25 minutes, créée par Tad Stones, produite par les studios Disney. Le premier épisode a été diffusé sur Disney Channel le 6 avril 1991 puis entre le 7 septembre 1991 et le 12 décembre 1992 sur ABC et des épisodes dans un ordre différent en syndication, puis rediffusée par la suite jusqu'au 29 août 1997.",119,"fr:Myster_Mask","https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Darkwing_Duck_1991_logo.svg/330px-Darkwing_Duck_1991_logo.svg.png",{"cats":["disney","persos_anim"]}],["Q2424228",204,"studio","Méchants de Disney","PC","Partant du principe formulé par Hitchcock que « plus réussi est le méchant, plus réussi sera le film », les studios Disney ont toujours apporté un grand soin à la conception des « méchants » peuplant leurs films et leurs bandes dessinées. Dès le premier court-métrage de Mickey Mouse en 1928, Steamboat Willie, Walt Disney a placé sur la route de ses héros des « affreux » en tous genres, du plus ridicule au plus dangereux, dont le seul but est de leur rendre la vie infernale.",115,"fr:Liste_des_méchants_de_Disney","c:c/c2/Mickey%27s_Not_So_Scary_Halloween_Party_-_Villians_Stage_Show_%283%29.jpg"],["Q241920",205,"studio","Neuf Sages de Disney","PC","Les Neuf Sages de Disney constituaient le noyau dur des animateurs Disney. Ils réalisèrent la plupart des chefs-d'œuvre du premier âge d'or des studios Disney, de Blanche-Neige et les Sept Nains aux Aventures de Bernard et Bianca.","Les Neuf Sages de Disney constituaient le noyau dur des animateurs Disney.","fr:Neuf_Sages_de_Disney","c:9/9e/Frankandollie.jpg"],["Q2252695",206,"studio","Paperman","C","Paperman est un court métrage d'animation américain en noir et blanc de John Kahrs, sorti en 2012.",null,"fr:Paperman","https://upload.wikimedia.org/wikipedia/en/thumb/2/24/Paperman_%282012%29_poster.jpg/330px-Paperman_%282012%29_poster.jpg"],["Q3366906",207,"studio","Partir là-bas","C","Partir là-bas est une chanson issue du film d'animation La Petite Sirène, sorti en 1989. La chanson a été composée par Alan Menken avec les paroles originales d'Howard Ashman.","Partir là-bas est une chanson issue du film d'animation La Petite Sirène, sorti en 1989.","fr:Partir_là-bas",""],["Q3908584",208,"studio","Pauvres âmes infortunées","C","« Pauvres âmes infortunées » est la chanson de la sorcière des mers Ursula dans La Petite Sirène (Disney, 1989), qui convainc Ariel de lui céder sa voix.","","en:Poor_Unfortunate_Souls",""],["Q357627",209,"studio","Pete Docter","PC","Pete Docter est un réalisateur, scénariste, producteur et acteur américain, né à Bloomington le 9 octobre 1968. Il est le directeur artistique de Pixar Animation Studios, chez qui il a réalisé Monstres et Cie, Là-haut, Vice-versa et Soul.","Pete Docter est un réalisateur, scénariste, producteur et acteur américain, né à Bloomington le 9 octobre 1968.","fr:Pete_Docter","c:f/fd/Pete_Docter_cropped_2009.jpg"],["Q460427",210,"studio","Phénomène Raven","PC","Phénomène Raven est une série télévisée américaine en cent épisodes de 25 minutes créée par Michael Poryes et Susan Sherman, produite par les studios Disney et diffusée entre le 17 janvier 2003 et le 10 novembre 2007 sur Disney Channel.",115,"fr:Phénomène_Raven","https://upload.wikimedia.org/wikipedia/fr/thumb/9/9e/Ph%C3%A9nom%C3%A8ne_Raven_Logo.png/330px-Ph%C3%A9nom%C3%A8ne_Raven_Logo.png",{"cats":["disney","enfance"]}],["Q24495873",211,"studio","Piper","C","Piper est un court métrage d'animation américain réalisé par Alan Barillaro et qui est sorti en première partie de Le Monde de Dory le 17 juin 2016. Il remporte l'Oscar du meilleur court métrage d'animation durant la 89e cérémonie des Oscars en 2017.",117,"fr:Piper_(court_métrage)","https://upload.wikimedia.org/wikipedia/fr/thumb/d/d4/Piper.png/330px-Piper.png"],["Q2734098",213,"studio","Quand on prie la bonne étoile","C","Quand on prie la bonne étoile est une chanson tirée du long métrage d'animation Pinocchio réalisé par les studios Disney et sorti en 1940.",113,"fr:Quand_on_prie_la_bonne_étoile",""],["Q47207729",214,"studio","Remember Me","C","Remember Me, est une chanson du film d'animation Pixar Coco sorti en 2016",null,"fr:Remember_Me_(chanson_de_Pixar)",""],["Q532423",215,"studio","Robert Iger","E","Robert Allen « Bob » Iger, né le 10 février 1951 à New York, est un dirigeant et entrepreneur américain. Il est le président-directeur général de The Walt Disney Company de 2005 à 2020 et le président du conseil d'administration de la même société du 25 février 2020 au 31 décembre 2021. Le 20 novembre 2022, il reprend la tête de la Walt Disney Company pour une durée de 2 ans.","Robert Allen « Bob » Iger, né le 10 février 1951 à New York, est un dirigeant et entrepreneur américain.","fr:Robert_Iger","c:4/44/2018_Bob_Iger_%28cropped%29.jpg"],["Q347432",216,"studio","Roy Oliver Disney","R","Roy Oliver Disney est un homme d'affaires et producteur américain, né le 24 juin 1893 à Chicago et mort le 20 décembre 1971 à Burbank.",118,"fr:Roy_Oliver_Disney","c:2/2d/Roy_O._Disney_with_Company_at_Press_Conference.jpg"],["Q2019676",217,"studio","Réflexion","C","Réflexion est une chanson écrite et produite par Matthew Wilder et David Zippel pour la bande originale du film d'animation de Disney Mulan sorti en 1998. Dans le film, la chanson est interprétée par la chanteuse et actrice philippine Lea Salonga, lauréate d'un Tony Award, dans le rôle de Mulan.",111,"fr:Réflexion_(chanson)",""],["Q3042281",218,"studio","Sifflez en travaillant","C","Sifflez en travaillant est une chanson du film d'animation Blanche-Neige et les Sept Nains sorti en 1937 des studios Disney.",116,"fr:Sifflez_en_travaillant","c:e/ee/Snow_white_1937_trailer_screenshot_%286%29.jpg"],["Q909166",219,"studio","Silly Symphonies","C","Les Silly Symphonies sont une série de courts métrages d'animation produits entre 1929 et 1939 par les studios Disney. Contrairement aux dessins animés mettant en scène Mickey Mouse, Donald Duck, Dingo ou encore Pluto, les Silly Symphonies n'ont pas de personnages récurrents à quelques exceptions près, comme Les Trois Petits Cochons, Le Lièvre et la Tortue et certains films avec Pluto. Les histoires prennent principalement leurs sources dans les contes populaires européens et américains.","Les Silly Symphonies sont une série de courts métrages d'animation produits entre 1929 et 1939 par les studios Disney.","fr:Silly_Symphonies",""],["Q3119769",220,"studio","Sous l'océan","C","Sous l'océan est une chanson issue du film d'animation La Petite Sirène, sorti en 1989. La chanson a été composée par Alan Menken avec les paroles originales d'Howard Ashman.","Sous l'océan est une chanson issue du film d'animation La Petite Sirène, sorti en 1989.","fr:Sous_l'océan","https://upload.wikimedia.org/wikipedia/en/thumb/9/9f/Sebastian_C._-_Under_the_Sea.jpg/330px-Sebastian_C._-_Under_the_Sea.jpg"],["Q13308931",221,"studio","Star Butterfly","PC","Star Butterfly est une série télévisée d'animation américaine en 77 épisodes doubles créés par Daron Nefcy et produite par Disney Television Animation.",118,"fr:Star_Butterfly","https://upload.wikimedia.org/wikipedia/fr/thumb/9/9f/Star_butterfly_logo.png/330px-Star_butterfly_logo.png"],["Q816038",222,"studio","Steamboat Willie","R","Steamboat Willie, ou Willie, le bateau à vapeur au Québec, est un court métrage d'animation américain, initialement muet, des studios Disney avec Mickey Mouse sorti en 1928. Troisième film de la série Mickey Mouse, il marque la naissance officielle du personnage. Il est également le premier à avoir bénéficié d'une bande sonore synchronisée dès sa sortie.",115,"fr:Steamboat_Willie","c:5/50/Steamboat_Willie_1928_Poster.png"],["Q906232",223,"studio","Studios Disney de 1989 à 1995","PC","L'histoire des Studios Disney de 1989 à 1995 est marquée par une renaissance et plusieurs succès dans le domaine de l'animation. Les origines de cette période sont à rechercher dans le changement de direction de la Walt Disney Company en 1984 et la volonté des nouveaux responsables de redorer le blason du studio.",115,"fr:Studios_Disney_de_1989_à_1995","c:3/3f/Roy_E._Disney.jpg"],["Q753848",224,"studio","Super Baloo","PC","Super Baloo ou Looping est une série télévisée d'animation américaine en 65 épisodes de 22 minutes, créée par Jymn Magon et Mark Zaslove d'après les personnages du Livre de la jungle, produite par les studios Disney et diffusée initialement sur Disney Channel le 5 mai 1990 au 8 août 1991 ainsi qu'en syndication entre le 10 septembre 1990 et le 2 septembre 1994. Un épisode spécial, servant de pilote pour la syndication, nommé Quand les pirates s'en mêlent a été diffusé le 7 septembre 1990.",114,"fr:Super_Baloo","c:f/f5/TaleSpin_logo.png"],["Q103",225,"studio","Supercalifragilisticexpialidocious","R","Supercalifragilisticexpialidocious est une chanson des frères Sherman figurant dans le film Mary Poppins sorti en 1964. Elle est principalement connue pour son titre, un hapax de 34 lettres.","Supercalifragilisticexpialidocious est une chanson des frères Sherman figurant dans le film Mary Poppins sorti en 1964.","fr:Supercalifragilisticexpialidocious","https://upload.wikimedia.org/wikipedia/en/thumb/6/63/Supercalifradgilisticexpialidocious_by_Julie_Andrews_and_Dick_Van_Dyke_US_vinyl.jpg/330px-Supercalifradgilisticexpialidocious_by_Julie_Andrews_and_Dick_Van_Dyke_US_vinyl.jpg"],["Q110713586",226,"studio","Sous pression","C","« Sous pression » (Surface Pressure) est la chanson de Luisa dans Encanto (Disney, 2021), où la grande sœur ultra-forte avoue crouler sous les attentes.","","en:Surface_Pressure","https://upload.wikimedia.org/wikipedia/en/thumb/5/58/Jessica_Darrow_-_Surface_Pressure_%28From_%22Encanto%29.png/330px-Jessica_Darrow_-_Surface_Pressure_%28From_%22Encanto%29.png"],["Q1070749",227,"studio","The Mickey Mouse Club","R","Le Club Mickey est un ensemble de trois émissions de télévision américaines. Diffusé entre le 3 octobre 1955 et le 10 août 2018 sur ABC et a été relancée dans les années 1970 puis les années 1990 sur Disney Channel. Ces émissions avaient comme principe commun d'inviter des enfants talentueux à chanter devant le public et ont permis de populariser de nombreux chanteurs, surnommés Mouseketeer.","Le Club Mickey est un ensemble de trois émissions de télévision américaines.","fr:The_Mickey_Mouse_Club","https://upload.wikimedia.org/wikipedia/fr/thumb/5/5a/Mickey_Mouse_Club_Logo.jpg/330px-Mickey_Mouse_Club_Logo.jpg"],["Q7414",228,"studio","The Walt Disney Company","M","The Walt Disney Company est une entreprise américaine créée en 1923 par Walt Disney sous le nom Disney Brothers Studio. Elle est le second groupe de divertissement au monde en 2025, présent dans l'industrie des médias avec des émissions, des séries télévisées, du cinéma avec des courts-métrages d'animation, des longs métrages d'animation et des films en prises de vues réelles, dans l'industrie du tourisme et de loisirs, ainsi que dans les produits dérivés de ses nombreuses productions.","The Walt Disney Company est une entreprise américaine créée en 1923 par Walt Disney sous le nom Disney Brothers Studio.","fr:The_Walt_Disney_Company","c:3/32/Walt_Disney_Studios_Alameda_Entrance.jpg",{"cats":["disney","marques"]}],["Q497155",229,"studio","Touchstone Pictures","PC","Touchstone Pictures est une filiale de Walt Disney Company créée pour produire des films destinés à un public plus adulte, réservant les productions associées à la famille et à la jeunesse au label Disney. Le label cinématographique a été créé en 1984 par Ron Miller et sa première production fut Splash. Les films de Touchstone, comme tous les films de Walt Disney Company, étaient distribués par Buena Vista International. Le studio disparait définitivement en 2016.",114,"fr:Touchstone_Pictures","https://upload.wikimedia.org/wikipedia/fr/thumb/d/d3/Touchstone_Pictures_logo.png/330px-Touchstone_Pictures_logo.png"],["Q336424",230,"studio","Ub Iwerks","PC","Ub Iwerks, né Ubbe Ert Iwwerks le 24 mars 1901 à Kansas City et mort le 7 juillet 1971 à Burbank, est un animateur et producteur américain, surtout connu pour son travail avec et pour Walt Disney, dont la création graphique de Mickey Mouse et Oswald le lapin chanceux, ainsi que pour les effets spéciaux du film Les Oiseaux d'Alfred Hitchcock, qui lui vaudront une nomination aux Oscars en 1964. Il a fait modifier son nom d'origine néerlandaise au début des années 1920.",117,"fr:Ub_Iwerks","c:8/84/Ub_Iwerks.jpg"],["Q1685941",231,"studio","Un jour mon prince viendra","C","Un jour mon prince viendra est une chanson du film d'animation Blanche-Neige et les Sept Nains sorti en 1937 des studios Disney. Cette chanson, sortie sous différents supports, fut classée numéro 1 en 1939 jusqu'en 1941, avec plus de 3,5 millions de copies vendues. Elle demeure un classique du répertoire enfantin mondial. Le 33 tours du film se vendit à plus de 2,5 millions d'exemplaires, et fut également numéro 1.",112,"fr:Un_jour_mon_prince_viendra","c:8/8e/SNOW_WHITE_DISNEY.jpg"],["Q3548944",232,"studio","Un poco loco","C","Un poco loco est une composition du pianiste de jazz américain Bud Powell. Le premier enregistrement date de la session du 1er mai 1951 pour le label Blue Note. Bud Powell était au piano, Curly Russell à la basse et Max Roach à la batterie. Le critique Harold Bloom a inclus cet enregistrement dans sa courte liste des meilleurs de l'art américain du XXe siècle.","Un poco loco est une composition du pianiste de jazz américain Bud Powell.","fr:Un_poco_loco","https://upload.wikimedia.org/wikipedia/en/thumb/b/ba/Un_Poco_Loco_Bud_Powell.jpg/330px-Un_Poco_Loco_Bud_Powell.jpg"],["Q8704",233,"studio","Walt Disney","M","Walter Disney, dit Walt Disney, né le 5 décembre 1901 à Chicago et mort le 15 décembre 1966 à Burbank, est un producteur, réalisateur, scénariste, acteur et animateur américain.",109,"fr:Walt_Disney","c:d/df/Walt_Disney_1946.JPG",{"cats":["disney","personnalites","usa"]}],["Q191224",234,"studio","Walt Disney Pictures","R","Walt Disney Pictures est un studio de production cinématographique créé le 1er avril 1983 comme une filiale de la société Walt Disney Productions, renommée Walt Disney Company en 1986. Il continue à produire ce qui formait le cœur de métier de la société Disney fondée en 1923 par Walt Disney, des films d'animation et d'autres en prise de vue réelle. Avant que cette filiale ne soit créée, il s'agissait d'un service interne de la compagnie.",113,"fr:Walt_Disney_Pictures","https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Walt_Disney_Pictures_text_logo.svg/330px-Walt_Disney_Pictures_text_logo.svg.png"],["Q110516869",235,"studio","Ne parlons pas de Bruno","C","« Ne parlons pas de Bruno » est la chanson d'Encanto (2021) écrite par Lin-Manuel Miranda. Elle est devenue le plus grand tube Disney depuis des décennies, numéro 1 aux États-Unis.","","en:We_Don't_Talk_About_Bruno","https://upload.wikimedia.org/wikipedia/en/thumb/b/bf/Encanto_-_We_Don%27t_Talk_About_Bruno.png/330px-Encanto_-_We_Don%27t_Talk_About_Bruno.png"],["Q18157125",236,"studio","Pour les hommes","C","« Pour les hommes » (You're Welcome) est la chanson du demi-dieu Maui dans Vaiana (Disney, 2016), où il se vante de tout ce qu'il a offert aux humains.","","en:You're_Welcome_(song)","https://upload.wikimedia.org/wikipedia/en/thumb/2/28/You%27re_Welcome_-_The_Beach_Boys.jpg/330px-You%27re_Welcome_-_The_Beach_Boys.jpg"],["Q3302365",237,"studio","You've Got a Friend in Me","C","You've Got a Friend in Me est une chanson de Randy Newman. Utilisée comme chanson principale du film d'animation Disney/Pixar Toy Story de 1995, elle est depuis devenue un élément musical majeur de ses suites, Toy Story 2, Toy Story 3 et Toy Story 4 ainsi qu'un leitmotiv musical tout au long de la franchise Toy Story. La chanson a été nommée pour l'Oscar de la meilleure chanson originale et le Golden Globe Award de la meilleure chanson originale.","You've Got a Friend in Me est une chanson de Randy Newman.","fr:You've_Got_a_Friend_in_Me","https://upload.wikimedia.org/wikipedia/en/thumb/5/55/You%27ve_Got_a_Friend_in_Me_album_cover_%28duet_version%29.png/330px-You%27ve_Got_a_Friend_in_Me_album_cover_%28duet_version%29.png"],["Q2842882",238,"studio","Zip-a-Dee-Doo-Dah","C","Zip-a-Dee-Doo-Dah est une chanson composée par Allie Wrubel, avec les paroles de Ray Gilbert, et apparue initialement dans le long-métrage d'animation des studios Disney Mélodie du Sud, sorti en 1946.",117,"fr:Zip-a-Dee-Doo-Dah",""],["Q2996360",239,"perso","Dr Heinz Doofenshmirtz","PC","Dr Heinz Doofenshmirtz est un personnage de bande-dessinée. On le retrouve dans Phinéas et Ferb. Créé par Dan Povenmire.",null,"en:Dr._Doofenshmirtz","https://upload.wikimedia.org/wikipedia/en/thumb/e/eb/Heinz_Doofenshmirtz.png/330px-Heinz_Doofenshmirtz.png",{"cats":["disney","persos_anim"]}],["Q2502489",240,"perso","Belle (personnage)","PC","Belle est un personnage de fiction des studios Disney, inspiré par le personnage du conte La Belle et la Bête de Jeanne-Marie Leprince de Beaumont. Elle est apparue pour la première fois dans le « Classique d'animation » La Belle et la Bête, en 1991.",112,"fr:Belle_%28Disney%29","c:7/77/Disneyland_2012-03-30_Belle.jpg"],["Q2278783",241,"perso","Tia Dalma","PC","Tia Dalma est un personnage fictif de la franchise Pirates des Caraïbes de Disney, qui fait ses débuts dans Pirates des Caraïbes : Le Secret du coffre maudit. C'est une pratiquante du vaudou et du hoodoo qui était autrefois amoureuse du pirate Davy Jones et qui l'a maudit après sa trahison. Dans le troisième film, Tia se révèle être l'apparence mortelle de Calypso, la déesse de la mer.",115,"fr:Tia_Dalma","c:0/0a/SDCC_2007_-_Tia_Dalma_%28954882677%29.jpg"],["Q20501302",242,"perso","Leader Suprême Snoke","PC","Snoke est un personnage de la saga cinématographique Star Wars. Créé par Palpatine peu après la bataille d'Endor, il devient le suprême leader du Premier Ordre jusqu'à sa mort. Il est assassiné par son apprenti Kylo Ren qui reprend son titre. Il est ensuite révélé qu'il est un clone créé par l'empereur Sith Palpatine.",116,"fr:Snoke","https://upload.wikimedia.org/wikipedia/en/thumb/4/4f/Snoke-The_Force_Awakens_%282015%29.png/330px-Snoke-The_Force_Awakens_%282015%29.png"],["Q2620474",243,"perso","Coccinelle (personnage)","PC","Coccinelle est un voiture d'une saga Disney. On le retrouve dans Un amour de Coccinelle.",null,"en:Herbie","c:1/1b/Herbie_car.jpg"],["Q1623044",244,"perso","Elizabeth Swann","C","Elizabeth Swann est l'héroïne de la saga Pirates des Caraïbes, jouée par Keira Knightley : fille du gouverneur devenue reine des pirates.",110,"fr:Elizabeth_Swann","https://upload.wikimedia.org/wikipedia/en/thumb/e/e2/ElizabethSwann.jpg/330px-ElizabethSwann.jpg"],["Q2559802",245,"perso","La Bête","C","La Bête est le nom donné au personnage de fiction issu du grand classique d'animation Disney La Belle et la Bête (1991).",null,"fr:La_B%C3%AAte_%28Disney%29","https://upload.wikimedia.org/wikipedia/en/thumb/4/4a/Disney-beast.PNG/330px-Disney-beast.PNG"],["Q21884092",246,"perso","Général Hux","C","Le général Armitage Hux, simplement appelé général Hux, est un personnage de fiction de l'univers de Star Wars, apparu pour la première fois dans l'épisode VII de la saga : Star Wars, épisode VII : Le Réveil de la Force.",111,"fr:G%C3%A9n%C3%A9ral_Hux","c:1/14/Domhnall_Gleeson_by_Gage_Skidmore.jpg"],["Q1764242",247,"perso","William Turner","C","William Turner est le forgeron devenu pirate de la saga Pirates des Caraïbes, joué par Orlando Bloom, fils de « Bootstrap » Bill Turner.",111,"fr:William_Turner_%28personnage%29","https://upload.wikimedia.org/wikipedia/en/thumb/9/96/Will_Turner_Caribbean.jpg/330px-Will_Turner_Caribbean.jpg"],["Q21782656",248,"perso","Poe Dameron","C","Poe Dameron est un personnage de fiction de l'univers Star Wars. Il est interprété par Oscar Isaac.",null,"fr:Poe_Dameron","c:f/f1/Oscar_Isaac_by_Gage_Skidmore.jpg"],["Q21772120",249,"perso","Finn","C","Finn est un personnage de fiction de l'univers Star Wars. Il est interprété par John Boyega dans les trois films de la troisième trilogie : Le Réveil de la Force, Les Derniers Jedi et L'Ascension de Skywalker.",115,"fr:Finn_%28Star_Wars%29","c:b/b6/John_Boyega_by_Gage_Skidmore.jpg"],["Q2630940",250,"perso","Akela","C","Akela est un personnage de fiction créé par Rudyard Kipling dans Le Livre de la jungle et Le Second Livre de la jungle. Il s'agit d'un loup des Indes, chef des loups du clan de Seeonee et président de leur « rocher du conseil ». C'est à l'un de ces conseils que le clan adopte l'enfant d'homme Mowgli comme l'un des siens, et Akela deviendra l'un de ses mentors.",111,"fr:Akela","c:a/a4/The_Two_Jungle_Books_1895_Akela%2C_the_Lone_Wolf.jpg"],["Q21541731",251,"perso","BB-8","C","BB-8 est un droïde de l'univers Star Wars. Il apparaît pour la première fois dans Star Wars, épisode VII : Le Réveil de la Force (2015).",116,"fr:BB-8","c:d/da/BB-8_figure_at_Madame_Tussauds_London.jpg"],["Q601747",252,"perso","Joshamee Gibbs","C","Joshamee Gibbs est le fidèle second de Jack Sparrow dans la saga Pirates des Caraïbes, joué par Kevin McNally.",null,"fr:Joshamee_Gibbs","https://upload.wikimedia.org/wikipedia/en/thumb/e/e3/Gibbs300px.PNG/330px-Gibbs300px.PNG"],["Q21790713",253,"perso","Phasma","C","La capitaine Phasma est un personnage de fiction de l'univers de Star Wars, apparu pour la première fois dans l'épisode VII de la saga : Le Réveil de la Force. Elle agit au sein du Premier Ordre en tant que commandante des légions de stormtroopers. Elle se distingue d'eux par une armure chromée et une cape noire à bordure rouge couvrant son épaule. Elle est interprétée par l'actrice Gwendoline Christie.",109,"fr:Phasma_%28Star_Wars%29","https://upload.wikimedia.org/wikipedia/en/thumb/f/fc/Captain_Phasma.png/330px-Captain_Phasma.png"],["Q22079436",254,"perso","Maz Kanata","C","Maz Kanata est un personnage de l'univers Star Wars. Elle apparaît pour la première fois dans Star Wars, épisode VII : Le Réveil de la Force. Il s'agit d'une humanoïde de très petite taille, à la peau orange et au visage rond particulièrement ridé. Âgée de plus de 1 000 ans, Maz est une pirate et contrebandière invétérée. Elle possède et gère une taverne abritée dans un château de la planète Takodana.",116,"fr:Maz_Kanata","https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/Lupita_Nyong%27o_%2836110769341%29.jpg/3840px-Lupita_Nyong%27o_%2836110769341%29.jpg"],["Q593185",255,"perso","James Norrington","C","Pirates des Caraïbes est une franchise de médias cinématographique sur la piraterie produite par Jerry Bruckheimer et Walt Disney Pictures. Elle est composée de cinq films, sortis entre 2003 et 2017. Le premier film reprend la thématique de l'attraction très populaire Pirates of the Caribbean ouverte en 1967 à Disneyland, en Californie, et utilisant le système audio-animatronic. La franchise suit les aventures du capitaine pirate Jack Sparrow, interprété par Johnny Depp.",114,"fr:James_Norrington","c:d/db/Pirates_of_the_Caribbean.jpg"],["Q671915",256,"perso","Cutler Beckett","C","Pirates des Caraïbes est une franchise de médias cinématographique sur la piraterie produite par Jerry Bruckheimer et Walt Disney Pictures. Elle est composée de cinq films, sortis entre 2003 et 2017. Le premier film reprend la thématique de l'attraction très populaire Pirates of the Caribbean ouverte en 1967 à Disneyland, en Californie, et utilisant le système audio-animatronic. La franchise suit les aventures du capitaine pirate Jack Sparrow, interprété par Johnny Depp.",114,"fr:Cutler_Beckett","c:d/db/Pirates_of_the_Caribbean.jpg"],["Q1812955",257,"perso","Badroulbadour","C","Badroulbadour est la princesse du conte Aladin ou la Lampe merveilleuse des Mille et Une Nuits. Disney s'en est inspiré pour la princesse Jasmine.",111,"en:Badroulbadour","c:6/66/Alad.jpg"],["Q66754020",258,"perso","Forky","C","Forky est un personnage dans Toy Story 4. Créé par John Lasseter.",null,"en:Forky","c:f/f8/Toy_Story_logo_2010.png"],["Q1199692",259,"perso","Le Petit Grille-pain courageux","PC","Le Petit Grille-pain courageux, ou Les magnifiques appareils électroménagers au Québec, est un film d'animation sorti en 1987 produit par les studios Hyperion Pictures et Kushner-Locke Company, distribué par Walt Disney Home Video.",111,"fr:Le_Petit_Grille-pain_courageux","https://upload.wikimedia.org/wikipedia/en/thumb/0/05/Brave_Little_Toaster_poster.jpg/330px-Brave_Little_Toaster_poster.jpg"],["Q549344",261,"perso","M. Patate","PC","M. Patate ou Monsieur Patate est un jouet destiné aux enfants permettant de créer différentes combinaisons amusantes sur un corps en forme de pomme de terre.",116,"fr:M._Patate_%28jouet%29","c:8/85/Disneyland_Hong_Kong_-_Toy_Story_Land_IMG_5462.JPG",{"cats":["disney","enfance"]}],["Q3134305",263,"perso","Elastigirl","C","Elastigirl, alias Hélène Parr, est la super-héroïne élastique des Indestructibles de Pixar : mère de famille, elle peut étirer son corps à volonté et forme avec Mr. Indestructible un couple de héros.",164,"fr:Elastigirl","https://upload.wikimedia.org/wikipedia/fr/thumb/f/f7/Les_Indestructibles_Logo.png/330px-Les_Indestructibles_Logo.png"],["Q3092255",268,"perso","Fée Clochette","C","Fée Clochette est un personnage développé par les studios Disney sur la base du personnage éponyme du roman Peter Pan de J. M. Barrie pour le long métrage Peter Pan (1953).",113,"fr:F%C3%A9e_Clochette_%28Disney%29","c:4/42/Tinker_Bell_-_Walt_Disney_animated_film.png"],["Q1427030",269,"perso","Winnie l'ourson","PC","Winnie l'ourson est un ours de fiction. On le retrouve dans Les Aventures de Winnie l'ourson. Créé par Alan Alexander Milne.",107,"en:Winnie_the_Pooh_%28Disney_character%29","https://upload.wikimedia.org/wikipedia/en/thumb/1/10/Winniethepooh.png/330px-Winniethepooh.png"],["Q326075",274,"perso","Rafiki","PC","Rafiki est un personnage de fiction qui est apparu pour la première fois dans le long métrage d'animation Le Roi lion. Le personnage apparaît dans la suite du film Le Roi lion 2 : L'Honneur de la tribu dans Le Roi lion 3 : Hakuna Matata et la série d'animation La Garde du Roi lion.",112,"fr:Rafiki_%28Disney%29",""],["Q3388787",275,"perso","Pinocchio","PC","Pinocchio est le personnage titre du long métrage d'animation Pinocchio (1940) adapté du conte éponyme de Carlo Collodi paru en 1881. La version créée par les studios Disney diffère des autres adaptations du conte, ce qui est l'objet de cette page.",111,"fr:Pinocchio_%28Disney%29","c:0/08/Pinokio_magic_kingdom.jpg"],["Q1625719",276,"perso","Empereur Zurg","C","L'Empereur Zurg est un personnage de fiction des films Toy Story et Toy Story 2. Il est mentionné dans le premier volet de la série, mais c'est seulement dans le second qu'il apparaît, ainsi qu'à la fin de Toy Story 3. Il apparaît également dans les jeux vidéo dérivés de la saga Toy Story, ainsi que dans l'attraction Buzz Lightyear's Astro Blasters et ses dérivés. Il est doublé en anglais par Andrew Stanton dans les films et par Wayne Knight dans la série animée.",113,"fr:Empereur_Zurg","c:f/fc/Buzz_Lightyear%27s_Space_Ranger_Spin.jpg"],["Q1627695",277,"perso","Kuzco","R","Kuzco est l'empereur inca égoïste de Kuzco, l'empereur mégalo (2000), transformé en lama par sa conseillère Yzma.",null,"https://disney.fandom.com/wiki/Kuzco","https://static.wikia.nocookie.net/disney/images/f/ff/Profile_-_Kuzco.jpeg/revision/latest/scale-to-width-down/400"],["Q1143257",278,"perso","Yzma","R","Yzma est la vieille conseillère maléfique de Kuzco, l'empereur mégalo, qui rate toutes ses tentatives de l'empoisonner.",null,"https://disney.fandom.com/wiki/Yzma","https://static.wikia.nocookie.net/disney/images/f/f2/Profile_-_Yzma.jpeg/revision/latest/scale-to-width-down/281"],["Q4356400",279,"perso","Kronk","R","Kronk est l'homme de main gentil et un peu naïf d'Yzma dans Kuzco, l'empereur mégalo, excellent cuisinier qui parle aux écureuils.",115,"https://disney.fandom.com/wiki/Kronk","https://static.wikia.nocookie.net/disney/images/6/64/Kronk_.jpg/revision/latest/scale-to-width-down/400"],["Q23042987",280,"perso","Judy Hopps","E","Judy Hopps est une lapine policière dans Zootopie (2016), la première de son espèce à intégrer la police de la ville.",null,"https://disney.fandom.com/wiki/Judy_Hopps","https://static.wikia.nocookie.net/disney/images/d/da/Profile_-_Judy_Hopps.jpeg/revision/latest/scale-to-width-down/300"],["Q24136041",281,"perso","Nick Wilde","E","Nick Wilde est un renard arnaqueur dans Zootopie, qui fait équipe avec Judy Hopps pour résoudre une affaire.",null,"https://disney.fandom.com/wiki/Nick_Wilde","https://static.wikia.nocookie.net/disney/images/5/50/Profile_-_Nick_Wilde.jpeg/revision/latest/scale-to-width-down/267"],["Fdis_hamm",282,"perso","Bayonne","R","Bayonne (Hamm) est le cochon-tirelire sarcastique de Toy Story, toujours prêt à lancer une remarque bien sentie.",null,"https://disney.fandom.com/wiki/Hamm","https://static.wikia.nocookie.net/disney/images/4/4f/Profile_-_Hamm.jpeg/revision/latest/scale-to-width-down/400"],["Q2152060",283,"perso","Rex","R","Rex est le dinosaure en plastique anxieux de Toy Story, qui rêve d'être effrayant mais a surtout peur de tout.",null,"https://disney.fandom.com/wiki/Rex","https://static.wikia.nocookie.net/disney/images/5/56/Profile_-_Rex.jpeg/revision/latest/scale-to-width-down/400"],["Q10749037",284,"perso","Lotso","E","Lotso est un ours en peluche à l'odeur de fraise, en apparence gentil, qui se révèle être le méchant de Toy Story 3.",null,"https://disney.fandom.com/wiki/Lotso","https://static.wikia.nocookie.net/disney/images/3/30/Profile_-_Lots-o%27-Huggin%27_Bear.jpg/revision/latest/scale-to-width-down/400"],["Q16594539",285,"perso","Léon","R","Léon (Randall Boggs) est le monstre caméléon rival de Sulli dans Monstres et Cie, prêt à tout pour devenir la meilleure terreur.",109,"https://disney.fandom.com/wiki/Randall_Boggs","https://static.wikia.nocookie.net/disney/images/4/47/Profile_-_Randall_Boggs.jpeg/revision/latest/scale-to-width-down/400"],["Q3160045",286,"perso","Sulli","E","Sulli (James P. Sullivan) est le grand monstre bleu à poils de Monstres et Cie, meilleure terreur de l'usine, qui s'attache à la petite Bouh.",113,"https://disney.fandom.com/wiki/Sulli","https://static.wikia.nocookie.net/disney/images/3/3c/Profile_-_Sulley.jpg/revision/latest/scale-to-width-down/400"],["Q3243336",287,"perso","Lilo Pelekai","E","Lilo Pelekai est la petite fille hawaïenne de Lilo et Stitch, qui adopte un « chien » qui se révèle être une créature extraterrestre.",108,"https://disney.fandom.com/wiki/Lilo","https://static.wikia.nocookie.net/disney/images/1/1f/Profile_-_Lilo.png/revision/latest/scale-to-width-down/387"],["Fdis_syndrome",288,"perso","Syndrome","R","Syndrome est le méchant des Indestructibles, ancien fan rejeté de Mr. Indestructible devenu un génie de la technologie avide de vengeance.",106,"https://disney.fandom.com/wiki/Syndrome","https://static.wikia.nocookie.net/disney/images/9/96/Profile_-_Syndrome.png/revision/latest/scale-to-width-down/377"],["Fdis_sebastien",289,"perso","Sébastien","R","Sébastien est le crabe chef d'orchestre de La Petite Sirène, chargé de surveiller Ariel, qui chante « Sous l'océan ».",null,"https://disney.fandom.com/wiki/Sébastien","https://static.wikia.nocookie.net/disney/images/c/ca/Profile_-_Sebastian.jpeg/revision/latest/scale-to-width-down/400"],["Fdis_russell",290,"perso","Russell","R","Russell est le jeune scout explorateur de Là-haut, embarqué par accident dans le voyage de la maison volante de Carl.",null,"https://disney.fandom.com/wiki/Russell","https://static.wikia.nocookie.net/disney/images/f/f7/Profile-Russell.png/revision/latest/scale-to-width-down/400"],["Fdis_doug",291,"perso","Doug","R","Doug est le chien bavard de Là-haut, qui parle grâce à un collier traducteur et s'exclame « Écureuil ! » dès qu'il est distrait.",114,"https://disney.fandom.com/wiki/Doug","https://static.wikia.nocookie.net/disney/images/c/c7/Profile-Dug2-jpeg.jpeg/revision/latest/scale-to-width-down/400"],["Fdis_roz",292,"perso","Roz","PC","Roz est la secrétaire limace de Monstres et Cie, éternellement blasée, qui rappelle à Bob qu'il n'a pas rempli ses papiers.",114,"https://disney.fandom.com/wiki/Roz","https://static.wikia.nocookie.net/disney/images/6/69/Profile_-_Roz.jpeg/revision/latest/scale-to-width-down/400"],["Fmuppet_chef",293,"perso","Le Chef suédois","E","Le Chef suédois est le cuisinier des Muppets, qui présente ses recettes dans un charabia pseudo-suédois incompréhensible (« Børk, børk, børk ! ») avant de finir en catastrophe, à coups de batte, de fusil ou d'ustensiles volants. Créé par Jim Henson et Frank Oz, il est l'une des marionnettes les plus cultes du Muppet Show.",103,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-chef.webp"],["Fmuppet_animal",294,"perso","Animal","E","Animal est le batteur déchaîné du groupe des Muppets, Dr. Teeth and the Electric Mayhem. Enchaîné à sa batterie pour éviter le pire, il ne s'exprime presque qu'en hurlements, dont son célèbre « Femmes ! Femmes ! ».",102,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-animal.webp"],["Fmuppet_gonzo",295,"perso","Gonzo","R","Gonzo le Grand est un Muppet au long nez crochu, artiste de cascades complètement folles et amoureux des poules, surtout de Camilla. Son espèce reste un mystère, jusqu'au film Les Muppets dans l'espace qui le fait venir d'une autre planète.",104,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-gonzo.webp"],["Fmuppet_fozzie",296,"perso","Fozzie","R","Fozzie est l'ours comique du Muppet Show, au petit chapeau et à la cravate à pois. Il enchaîne des blagues nulles en criant « Wocka wocka ! » et se fait régulièrement huer par Statler et Waldorf. C'est le meilleur ami de Kermit.",98,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-fozzie.webp"],["Fmuppet_statler",297,"perso","Statler et Waldorf","R","Statler et Waldorf sont les deux vieux grincheux installés dans la loge du théâtre du Muppet Show. Ils critiquent et se moquent de chaque numéro, avant d'éclater de rire à leurs propres vannes.",102,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-statler.webp"],["Fmuppet_beaker",298,"perso","Beaker","R","Beaker est l'assistant du professeur Bunsen dans le laboratoire Muppet. Cobaye malgré lui de toutes les expériences ratées, il ne s'exprime qu'en « Mi-mi-mi ! » paniqués.",103,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-beaker.webp"],["Fmuppet_bunsen",299,"perso","Professeur Bunsen","PC","Le professeur Bunsen Honeydew dirige le laboratoire Muppet. Ce scientifique chauve et souriant présente des inventions qui finissent presque toujours par exploser… sur son assistant Beaker.",103,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-bunsen.webp"],["Fmuppet_rowlf",300,"perso","Rowlf","PC","Rowlf est le chien pianiste du Muppet Show, calme et pince-sans-rire. C'est l'un des plus anciens Muppets de Jim Henson : il est apparu dans des publicités dès 1962.",97,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-rowlf.webp"],["Fmuppet_scooter",301,"perso","Scooter","PC","Scooter est le régisseur du Muppet Show, toujours en veste et à lunettes, qui court en coulisses pour prévenir les artistes. Il a obtenu son poste grâce à son oncle, propriétaire du théâtre.",101,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-scooter.webp"],["Fmuppet_sam",302,"perso","Sam l'Aigle","PC","Sam l'Aigle est le Muppet le plus coincé : un pygargue à tête blanche très patriote, défenseur de la morale, outré par tout ce qui se passe dans le spectacle.",100,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-sam.webp"],["Fmuppet_rizzo",303,"perso","Rizzo le rat","PC","Rizzo est un rat râleur et débrouillard, qui forme un duo comique avec Gonzo dans de nombreux films, dont Noël chez les Muppets et L'Île au trésor des Muppets.",100,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-rizzo.webp"],["Fmuppet_pepe",304,"perso","Pepé","PC","Pepé est une crevette royale à l'accent espagnol, dragueur et vantard, qui rejoint la bande des Muppets à la fin des années 1990. Il insiste : il n'est pas une crevette, mais une crevette « royale », okay ?",103,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-pepe.webp"],["Fmuppet_teeth",305,"perso","Dr. Teeth","PC","Dr. Teeth est le chef du groupe Dr. Teeth and the Electric Mayhem. Claviériste au sourire en or et au style hippie flamboyant, il parle avec un vocabulaire aussi fleuri que ses tenues.",101,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-teeth.webp"],["Fmuppet_camilla",306,"perso","Camilla la poule","C","Camilla est la poule dont Gonzo est fou amoureux. Elle ne s'exprime qu'en caquetant, ce qui ne l'empêche pas de mener la danse dans plusieurs films des Muppets.",104,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-camilla.webp"],["Fmuppet_janice",307,"perso","Janice","C","Janice est la guitariste du groupe Electric Mayhem, cool et rêveuse, avec ses grandes lèvres et ses longs cheveux blonds.",99,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-janice.webp"],["Fmuppet_floyd",308,"perso","Floyd Pepper","C","Floyd Pepper est le bassiste du groupe Electric Mayhem, cheveux roux et répliques sarcastiques, souvent chargé de garder Animal sous contrôle.",103,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-floyd.webp"],["Fmuppet_zoot",309,"perso","Zoot","C","Zoot est le saxophoniste du groupe Electric Mayhem, toujours à moitié endormi derrière ses lunettes de soleil.",null,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-zoot.webp"],["Fmuppet_sweetums",310,"perso","Sweetums","C","Sweetums est un ogre géant et poilu, effrayant au premier regard mais gentil comme tout, qui apparaît régulièrement dans les spectacles des Muppets.",101,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-sweetums.webp"],["Fmuppet_harry",311,"perso","Crazy Harry","C","Crazy Harry est le pyromane du Muppet Show : il ne peut pas s'empêcher de faire exploser tout ce qui l'entoure, en ricanant.",100,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-harry.webp"],["Fmuppet_lew",312,"perso","Lew Zealand","C","Lew Zealand est l'artiste du Muppet Show qui lance des poissons… qui reviennent comme des boomerangs.",null,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-lew.webp"],["Fmuppet_walter",313,"perso","Walter","C","Walter est le Muppet héros du film Les Muppets, le retour (2011). Grand fan des Muppets, il aide à réunir la troupe et découvre son propre talent : siffler.",98,"fr:Le_Muppet_Show","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/muppet-walter.webp"],["Q3929702",314,"perso","Rajah","PC","Rajah est le tigre du Bengale de la princesse Jasmine dans Aladdin (1992). Compagnon fidèle et protecteur, il chasse les prétendants qui déplaisent à sa maîtresse, mais se comporte avec elle comme un gros chat.",116,"fr:Rajah_(Disney)","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/arena/rajah.webp"]]]);